function sim({mv, bc, dragC, wind=0, dt=1/1000, maxT=3, zeroRange=100, targetRange=600, elev=0}) {
  // solve zero angle if zeroRange provided
  function shoot(angle, targetDist, wantImpact=false) {
    let p={x:0,y:0,z:0};
    let dir={x:0,y:Math.sin(angle),z:Math.cos(angle)};
    let v={x:dir.x*mv,y:dir.y*mv,z:dir.z*mv};
    let maxY=0, t=0;
    let impact=null;
    while(t<maxT){
      const vRel={x:v.x-wind,y:v.y,z:v.z};
      const sp=Math.hypot(vRel.x,vRel.y,vRel.z);
      const k=dragC/bc;
      const a={x:-k*sp*vRel.x, y:-9.81-k*sp*vRel.y, z:-k*sp*vRel.z};
      v.x+=a.x*dt; v.y+=a.y*dt; v.z+=a.z*dt;
      p.x+=v.x*dt; p.y+=v.y*dt; p.z+=v.z*dt;
      t+=dt;
      maxY=Math.max(maxY,p.y);
      if(p.z>=targetDist){ impact={...p,t}; break;}
    }
    return impact;
  }
  // binary search angle for zero range
