function loadCareer(){
  try {
    const raw = localStorage.getItem(SAVE_KEY);
    if (!raw) return;
    const s = JSON.parse(raw);
    if (s && s.version === 1) {
      career = Object.assign(defaultCareer(), s);
      career.totals = Object.assign(defaultCareer().totals, s.totals || {});
      career.settings = Object.assign({mute:false}, s.settings || {});
      career.upgrades = Object.assign(defaultCareer().upgrades, s.upgrades || {});
      if (!RIFLE_BY_ID[career.rifle]) career.rifle = 'm24';
      if (!AMMO_BY_ID[career.ammo]) career.ammo = 'm80';
      if (!career.ownedRifles.includes(career.rifle)) career.ownedRifles.push(career.rifle);
      if (!career.ownedAmmo.includes(career.ammo)) career.ownedAmmo.push(career.ammo);
    }
  } catch(e){}
}
function saveCareer(){ try { localStorage.setItem(SAVE_KEY, JSON.stringify(career)); } catch(e){} }
loadCareer();

/* ---------- loadout computation ---------- */
function getLoadout(){
  const rifle = RIFLE_BY_ID[career.rifle] || RIFLES[0];
  const ammo = AMMO_BY_ID[career.ammo] || AMMO[0];
  const up = career.upgrades[rifle.id] || {barrel:0,optic:0,stock:0,trigger:0};
  const mv = rifle.mv * ammo.mv * (1 + 0.04*(up.barrel||0));
  const bc = rifle.bc * ammo.bc;
  const fov = rad(rifle.fov) * Math.pow(0.92, up.optic||0);
  const sway = rifle.sway * Math.pow(0.85, up.stock||0);
  const spread = rifle.spread * Math.pow(0.80, up.trigger||0);
  return { rifle, ammo, up, mv, bc, fov, sway, spread, zoom: 60/rifle.fov * Math.pow(1.08, up.optic||0) };
}
function formatRangeBand(cfg){ return `${cfg.rmin}–${cfg.rmax} m`; }
function opConfig(n){
  if (n <= OPS.length) return OPS[n-1];
  const base = OPS[OPS.length-1];
  const extra = n - OPS.length;
  return Object.assign({}, base, {
    name:'VETERAN ' + String(n).padStart(2,'0'),
    targets: Math.min(12, base.targets + Math.ceil(extra/2)),
    rmin: Math.min(720, base.rmin + extra*12), rmax: Math.min(820, base.rmax + extra*12),
    wmin: Math.min(12, base.wmin + extra*0.5), wmax: Math.min(14, base.wmax + extra*0.5),
    time: Math.max(115, base.time - extra*4), reward: base.reward + extra*0.18,
    threat:'EXTREME', weather: extra%2 ? 'rain' : 'fog',
    note:'A veteran sector. Every correction is harder, every window shorter. The valley remembers.'
  });
}

