    targets: Math.min(12, base.targets + Math.ceil(extra/2)),
    rmin: Math.min(720, base.rmin + extra*12), rmax: Math.min(820, base.rmax + extra*12),
    wmin: Math.min(12, base.wmin + extra*0.5), wmax: Math.min(14, base.wmax + extra*0.5),
    time: Math.max(115, base.time - extra*4), reward: base.reward + extra*0.18,
    threat:'EXTREME', weather: extra%2 ? 'rain' : 'fog',
    note:'A veteran sector. Every correction is harder, every window shorter. The valley remembers.'
  });
}

/* ============================================================
   SCENE STATE / WORLD
   ============================================================ */
const GROUND_Y = -24;
const EYE_Y = 0;
let state = 'title';
let currentWeather = 'clear';
let ambientTime = 0;
let world = null;
let mission = null;
let scope = null;
let bullets = [];
let effects = [];
let floaters = [];
let feedItems = [];
let timeScale = 1, slowmoT = 0;
let screenFlash = 0, lightning = 0, lightningTimer = 12;
let lastHudUpdate = 0;
let pointerLocked = false;
let showHelp = true;
let muted = false;

const attract = { yaw:0.03, pitch:-0.055, t:0 };
const view = { yaw:0, pitch:-0.06, fov:rad(62), zoomT:0, recoilYaw:0, recoilPitch:0, shake:0, swayYaw:0, swayPitch:0 };
const aim = { yaw:0, pitch:-0.06 };
const mouse = { dx:0, dy:0, left:false, right:false };
const keys = {};
const gamepadState = { index:-1, name:'', prev:{}, axes:[0,0,0,0], fire:0, scope:0, breath:0 };

function weather(){ return WEATHER[currentWeather] || WEATHER.clear; }
function fogAmount(z){
  const vis = weather().vis;
  return clamp(Math.pow(clamp(z/vis,0,1),1.18) * 0.96, 0, 0.94);
}
function fogged(hex,z){ return mixHex(hex, weather().fog, fogAmount(z)); }
function focal(){ return (H/2) / Math.tan(view.fov/2); }
function horizonY(){ return H/2 + focal()*Math.tan(view.pitch); }

function project(x,y,z){
  const cy = Math.cos(view.yaw), sy = Math.sin(view.yaw);
  const x1 = x*cy - z*sy;
  const z1 = x*sy + z*cy;
  const cp = Math.cos(view.pitch), sp = Math.sin(view.pitch);
  const y2 = y*cp - z1*sp;
  const z2 = y*sp + z1*cp;
  if (z2 <= 0.12) return null;
  const f = focal();
  return { x: W/2 + x1*f/z2, y: H/2 - y2*f/z2, z: z2, s: f/z2 };
}

function terrainSeed(){ return 918273; }

function generateWorld(){
  const rand = mulberry32(terrainSeed());
  const fields = [];
  const zs = [55,105,170,250,345,455,580,720,875,1045,1230,1430,1650,1900];
  const xs = [-1600,-1320,-1060,-820,-590,-370,-170,20,200,390,590,810,1060,1340,1600];
  const palette = ['#66764b','#5e7048','#77804e','#6e6744','#596b42','#7d7b4f','#54683f','#696b45'];
  for (let i=0;i<zs.length-1;i++){
    for (let j=0;j<xs.length-1;j++){
      const x0=xs[j], x1=xs[j+1], z0=zs[i], z1=zs[i+1];
      const h = (j*37 + i*91 + Math.floor(rand()*7)) % palette.length;
      fields.push({ x0,x1,z0,z1, color:palette[h], lines: rand()<0.22 && z1<760, tone:0.9+rand()*0.2 });
    }
  }
  // river ribbon
  const river = [];
  for (let z=120; z<=1900; z+=38){
    const cx = 118*Math.sin(z*0.0031+1.1) + 55*Math.sin(z*0.009+0.2) + 30;
    const w = 9 + 3.5*Math.sin(z*0.012);
    river.push({z, x:cx, w});
  }
  // road ribbon
  const road = [];
  for (let z=70; z<=1900; z+=42){
    const cx = -90 + z*0.035 + 36*Math.sin(z*0.004);
    road.push({z, x:cx, w:4.4});
  }
  const props = [];
  const add = (p) => props.push(p);
  const treeCols = ['#3f5835','#435e37','#36502f','#4a6239','#2f482b'];
  const bushCols = ['#4a5f39','#536a3f','#3e5433'];
  const rockCols = ['#797b6d','#686c61','#8a8979'];

  // scattered trees
  for (let i=0;i<155;i++){
    const z = 75 + rand()*1480;
    const x = (rand()*2-1)*(420 + z*0.62);
    const tall = 6 + rand()*9;
    const kind = rand() < 0.56 ? 'pine' : 'broad';
    add({ type:kind, x, z, h:tall, w:1.8+rand()*2.6, seed:rand()*99, color:treeCols[(rand()*treeCols.length)|0] });
  }
  // bushes & rocks
  for (let i=0;i<130;i++){
    const z = 45 + rand()*820;
    const x = (rand()*2-1)*(160 + z*0.8);
    add({ type:'bush', x, z, h:0.7+rand()*1.1, w:1.0+rand()*1.5, seed:rand()*99, color:bushCols[(rand()*bushCols.length)|0] });
  }
  for (let i=0;i<52;i++){
    const z = 40 + rand()*900;
    const x = (rand()*2-1)*(110 + z*0.85);
    add({ type:'rock', x, z, h:0.5+rand()*1.6, w:0.8+rand()*2.2, seed:rand()*99, color:rockCols[(rand()*rockCols.length)|0] });
  }
  for (let i=0;i<26;i++){
    const z = 35 + rand()*180;
    const x = (rand()*2-1)*(20 + z*1.4);
    add({ type:'grass', x, z, h:1.1+rand()*1.6, w:0.8+rand()*1.3, seed:rand()*99, color:'#4d6339' });
  }
  // hay bales
  for (let i=0;i<12;i++){
    add({ type:'hay', x:(rand()*2-1)*(80+rand()*380), z:120+rand()*700, h:1.2+rand()*0.4, w:1.7+rand()*0.7, seed:rand()*99, color:'#a58c51' });
  }
  // farm buildings
  const buildings = [
    {x:130,z:720,w:15,d:10,h:7,roof:3.2,kind:'barn'},
    {x:-210,z:860,w:12,d:9,h:5.5,roof:2.8,kind:'house'},
    {x:-165,z:815,w:6,d:6,h:4.2,roof:1.6,kind:'shed'},
    {x:60,z:1090,w:18,d:11,h:7.5,roof:3.4,kind:'barn'},
    {x:245,z:1165,w:11,d:8,h:5,roof:2.6,kind:'house'},
    {x:300,z:1120,w:8,d:7,h:4.5,roof:2.0,kind:'house'},
    {x:-420,z:1080,w:13,d:9,h:6,roof:3.0,kind:'house'},
    {x:-55,z:1380,w:20,d:12,h:8,roof:3.8,kind:'barn'},
    {x:430,z:1420,w:10,d:8,h:5,roof:2.4,kind:'house'}
  ];
  for (const b of buildings) add(Object.assign({type:'building', seed:rand()*99}, b));
  add({type:'silo', x:168, z:715, w:4.2, h:12, seed:rand()*99});
  add({type:'silo', x:102, z:1098, w:5, h:14, seed:rand()*99});
  add({type:'tower', x:-330, z:980, w:5, h:16, seed:rand()*99});
  add({type:'antenna', x:520, z:1260, w:2.2, h:34, seed:rand()*99});
  // trucks
  add({type:'truck', x:190, z:690, w:6.5, h:2.6, seed:rand()*99});
  add({type:'truck', x:-380, z:1120, w:6, h:2.5, seed:rand()*99});
  // fences
  const fences = [
    {x:0,z:410,span:210,seed:rand()*99},
    {x:0,z:640,span:260,seed:rand()*99},
    {x:0,z:930,span:320,seed:rand()*99},
    {x:-180,z:1180,span:220,seed:rand()*99}
  ];
  for (const f of fences) add({type:'fence', x:f.x, z:f.z, span:f.span, h:1.2, seed:f.seed});
  // power poles along the road
  for (let i=0;i<9;i++){
    const z = 180 + i*185;
    const cx = -90 + z*0.035 + 36*Math.sin(z*0.004);
    add({type:'pole', x:cx+12, z, h:11, seed:rand()*99});
  }
  // clouds & birds
  const clouds = [];
  for (let i=0;i<9;i++) clouds.push({az:-1.2+rand()*2.4, el:0.07+rand()*0.23, w:0.18+rand()*0.26, h:0.035+rand()*0.05, a:0.25+rand()*0.4, drift:0.002+rand()*0.004});
  const birds = [];
  for (let i=0;i<3;i++) birds.push({az:-0.7+rand()*1.4, el:0.11+rand()*0.16, w:0.055+rand()*0.05, speed:0.008+rand()*0.012, seed:rand()*99});
  world = { fields, river, road, props, clouds, birds, propsSorted: props.slice().sort((a,b)=>b.z-a.z) };
}

/* ---------- screen-space helpers for ground ---------- */
function drawQuadPts(pts, fill, stroke){
  if (!pts || pts.some(p=>!p)) return;
  ctx.beginPath();
  ctx.moveTo(pts[0].x, pts[0].y);
  for (let i=1;i<pts.length;i++) ctx.lineTo(pts[i].x, pts[i].y);
  ctx.closePath();
  if (fill){ ctx.fillStyle = fill; ctx.fill(); }
  if (stroke){ ctx.strokeStyle = stroke; ctx.lineWidth = 1; ctx.stroke(); }
}
function groundPoint(x,z){
  return project(x, GROUND_Y, z);
}
function inScreen(p, m=80){ return p && p.x > -m && p.x < W+m && p.y > -m && p.y < H+m; }

