function inScreen(p, m=80){ return p && p.x > -m && p.x < W+m && p.y > -m && p.y < H+m; }

/* ============================================================
   SKY / TERRAIN RENDER
   ============================================================ */
function screenAngleAt(x){ return Math.atan((x - W/2) / focal()); }
function mountainElev(az, layer){
  const s = terrainSeed()*0.001;
  if (layer === 0) return 0.012 + 0.008*Math.sin(az*2.1+s) + 0.005*Math.sin(az*5.7+1.7) + 0.003*Math.sin(az*11.3+4.1);
  if (layer === 1) return 0.0065 + 0.0055*Math.sin(az*3.3+2.2) + 0.0035*Math.sin(az*8.2+0.6) + 0.002*Math.sin(az*17.1+3.4);
  return 0.0030 + 0.0028*Math.sin(az*4.4+3.1) + 0.0020*Math.sin(az*13.7+1.2) + 0.0012*Math.sin(az*31.0+0.4);
}
function drawSky(){
  const w = weather();
  const g = ctx.createLinearGradient(0,0,0,H*0.92);
  g.addColorStop(0, w.skyTop);
  g.addColorStop(0.52, mixHex(w.skyTop, w.skyMid, 0.78));
  g.addColorStop(0.78, w.skyMid);
  g.addColorStop(1, w.skyLow);
  ctx.fillStyle = g; ctx.fillRect(0,0,W,H);

  // sun / moon glow
  const D = 7000;
  const sunP = project(Math.sin(w.sunAz)*D, Math.tan(w.sunEl)*D, Math.cos(w.sunAz)*D);
  if (sunP && sunP.z > 0){
    const r = clamp(260 / Math.max(0.4, view.fov/rad(60)), 90, 420);
    const gg = ctx.createRadialGradient(sunP.x,sunP.y,2,sunP.x,sunP.y,r);
    gg.addColorStop(0, alpha(w.sun, currentWeather === 'dusk' ? 0.95 : 0.7));
    gg.addColorStop(0.12, alpha(w.sun, 0.35));
    gg.addColorStop(0.45, alpha(w.sun, 0.1));
    gg.addColorStop(1, alpha(w.sun, 0));
    ctx.fillStyle = gg; ctx.beginPath(); ctx.arc(sunP.x,sunP.y,r,0,TAU); ctx.fill();
    if (sunP.x > -200 && sunP.x < W+200 && sunP.y > -200 && sunP.y < H+200){
      ctx.fillStyle = alpha('#ffffff', currentWeather==='dusk'?0.72:0.55);
      ctx.beginPath(); ctx.arc(sunP.x,sunP.y, currentWeather==='dusk'?8:5, 0, TAU); ctx.fill();
    }
  }

  // clouds
  for (const c of world.clouds){
    const az = c.az + ambientTime*c.drift*0.05;
    const el = c.el + Math.sin(ambientTime*0.02+c.az*9)*0.004;
    const p0 = project(Math.sin(az)*5200, Math.tan(el)*5200, Math.cos(az)*5200);
    if (!p0 || p0.z <= 0) continue;
    const f = focal();
    const wpx = (f/5200) * 5200 * Math.tan(c.w);
    const hpx = Math.max(7, wpx * 0.17);
    if (p0.x < -wpx || p0.x > W+wpx || p0.y < -hpx || p0.y > H+hpx) continue;
    ctx.save();
    ctx.globalAlpha = c.a * (0.45 + 0.55*Math.max(0, Math.cos((az-view.yaw)*0.9)));
    ctx.fillStyle = w.cloud;
    for (let i=0;i<5;i++){
      const ox = (i-2)*wpx*0.32;
      const oy = Math.sin(c.az*10+i*2.1)*hpx*0.22;
      ctx.beginPath(); ctx.ellipse(p0.x+ox, p0.y+oy, wpx*(0.34-Math.abs(i-2)*0.04), hpx*(0.8+0.18*Math.sin(i*2.4)), 0,0,TAU); ctx.fill();
    }
    ctx.restore();
  }

  // mountain layers
  const layers = [
    {base:0.0, col:mixHex(w.skyLow,w.fog,0.38), snow:0.5, step:7},
    {base:0.0, col:mixHex(w.groundDark,w.fog,0.56), snow:0.0, step:6},
    {base:0.0, col:mixHex(w.groundDark,w.fog,0.34), snow:0.0, step:4}
  ];
  const f = focal();
  for (let li=0; li<3; li++){
    const L = layers[li];
    ctx.beginPath();
    let first = true;
    for (let x=-24; x<=W+24; x+=L.step){
      const az = view.yaw + screenAngleAt(x);
      let el = mountainElev(az, li);
      if (li === 2) el *= 0.62;
      const yy = H/2 - f*Math.tan(clamp(el - view.pitch, -1.2, 1.2));
      if (first){ ctx.moveTo(x, yy); first = false; }
      else ctx.lineTo(x, yy);
    }
    ctx.lineTo(W+30,H+40); ctx.lineTo(-30,H+40); ctx.closePath();
    ctx.fillStyle = L.col; ctx.fill();
    if (li === 0){
      ctx.strokeStyle = alpha(w.skyLow, 0.18); ctx.lineWidth = 1.5; ctx.stroke();
    }
  }

  // horizon haze
  const hy = horizonY();
  if (hy > -80 && hy < H+80){
    const gg = ctx.createLinearGradient(0,hy-46,0,hy+54);
    gg.addColorStop(0, alpha(w.fog,0));
    gg.addColorStop(0.55, alpha(w.fog,0.62));
    gg.addColorStop(1, alpha(w.fog,0));
    ctx.fillStyle = gg; ctx.fillRect(0,hy-46,W,100);
  }

  // birds
  for (const b of world.birds){
    const az = b.az + Math.sin(ambientTime*0.07+b.seed)*0.06 + b.speed*Math.sin(ambientTime*0.13);
    const p = project(Math.sin(az)*2600, Math.tan(b.el+0.01*Math.sin(ambientTime*0.4+b.seed))*2600, Math.cos(az)*2600);
    if (!p || p.z <= 0 || p.x < -30 || p.x > W+30 || p.y < -30 || p.y > H) continue;
    const sz = clamp(b.w*45, 2, 8);
    const flap = Math.sin(ambientTime*3.1+b.seed*7)*0.5+0.5;
    ctx.strokeStyle = alpha('#26302a', 0.55);
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.moveTo(p.x-sz, p.y+flap*sz*0.3); ctx.quadraticCurveTo(p.x-sz*0.4,p.y-sz*0.4,p.x,p.y);
    ctx.quadraticCurveTo(p.x+sz*0.4,p.y-sz*0.4,p.x+sz,p.y+flap*sz*0.3);
    ctx.stroke();
  }
}

function drawGround(){
  const w = weather();
  const hy = horizonY();
  const top = clamp(hy, -60, H+40);
  if (top < H){
    const g = ctx.createLinearGradient(0, top, 0, H);
    g.addColorStop(0, mixHex(w.ground, w.fog, 0.86));
    g.addColorStop(0.22, mixHex(w.ground, w.fog, 0.52));
    g.addColorStop(0.65, w.ground);
    g.addColorStop(1, w.groundDark);
    ctx.fillStyle = g;
    ctx.fillRect(0, top, W, H-top+2);
  }
  if (top > 0){
    // sky above horizon: darkened lower atmosphere
    const g = ctx.createLinearGradient(0, Math.max(0,top-180), 0, top);
    g.addColorStop(0, alpha(w.fog,0));
    g.addColorStop(1, alpha(w.fog,0.55));
    ctx.fillStyle = g; ctx.fillRect(0, Math.max(0,top-180), W, 180);
  }
}

function drawFields(){
  if (!world) return;
  const w = weather();
  const f = focal();
  for (const p of world.fields){
    const centre = groundPoint((p.x0+p.x1)/2, (p.z0+p.z1)/2);
    if (!centre) continue;
    if (centre.x < -220 || centre.x > W+220 || centre.y < -120 || centre.y > H+180) continue;
    const p0 = groundPoint(p.x0,p.z0), p1 = groundPoint(p.x1,p.z0), p2 = groundPoint(p.x1,p.z1), p3 = groundPoint(p.x0,p.z1);
    if (!p0 || !p1 || !p2 || !p3) continue;
    const zmid = (p.z0+p.z1)/2;
    const col = fogged(shade(p.color, p.tone), zmid);
    ctx.beginPath();
    ctx.moveTo(p0.x,p0.y); ctx.lineTo(p1.x,p1.y); ctx.lineTo(p2.x,p2.y); ctx.lineTo(p3.x,p3.y); ctx.closePath();
    ctx.fillStyle = col; ctx.fill();
    if (p.lines && zmid < 700){
      ctx.strokeStyle = alpha(w.groundDark, 0.17);
      ctx.lineWidth = 1;
      for (let i=1;i<=2;i++){
        const t=i/3;
        const a1 = groundPoint(lerp(p.x0,p.x1,t), p.z0);
        const a2 = groundPoint(lerp(p.x0,p.x1,t), p.z1);
        if (a1 && a2){ ctx.beginPath(); ctx.moveTo(a1.x,a1.y); ctx.lineTo(a2.x,a2.y); ctx.stroke(); }
      }
    }
  }
}

function drawRibbon(points, widthKey, color, highlight){
  if (!points || !world) return;
  const w = weather();
  for (let i=0;i<points.length-1;i++){
    const a = points[i], b = points[i+1];
    const x0 = a.x - (a[widthKey]||1), x1 = a.x + (a[widthKey]||1);
    const x2 = b.x + (b[widthKey]||1), x3 = b.x - (b[widthKey]||1);
    const p0 = groundPoint(x0,a.z), p1 = groundPoint(x1,a.z), p2 = groundPoint(x2,b.z), p3 = groundPoint(x3,b.z);
    if (!p0 || !p1 || !p2 || !p3) continue;
    const zmid = (a.z+b.z)/2;
    if (p0.x < -100 && p1.x < -100 && p2.x < -100 && p3.x < -100) continue;
    if (p0.x > W+100 && p1.x > W+100 && p2.x > W+100 && p3.x > W+100) continue;
    ctx.beginPath();
    ctx.moveTo(p0.x,p0.y); ctx.lineTo(p1.x,p1.y); ctx.lineTo(p2.x,p2.y); ctx.lineTo(p3.x,p3.y); ctx.closePath();
    ctx.fillStyle = fogged(color, zmid); ctx.fill();
    if (highlight && zmid < 680){
      const c0 = groundPoint(a.x, a.z), c1 = groundPoint(b.x, b.z);
      if (c0 && c1){ ctx.strokeStyle = alpha(highlight, 0.22*fogAmount(zmid)+0.05); ctx.lineWidth = 1; ctx.beginPath(); ctx.moveTo(c0.x,c0.y); ctx.lineTo(c1.x,c1.y); ctx.stroke(); }
    }
  }
}

function drawRiver(){
  const w = weather();
  const water = currentWeather==='rain' ? '#687a78' : currentWeather==='dusk' ? '#6e6d69' : '#5f7f83';
  drawRibbon(world.river, 'w', water, currentWeather==='dusk'?'#e0a56a':'#c3d8d0');
}
function drawRoad(){
  drawRibbon(world.road, 'w', '#8b7d5e', null);
}

/* ============================================================
   PROP DRAWING
   ============================================================ */
function drawShadow(x, z, wm, dm, alphaV=0.16){
  const p = project(x, GROUND_Y+0.03, z);
  if (!p) return;
  const w = wm*p.s, h = Math.max(1, dm*p.s*0.34);
  ctx.fillStyle = alpha('#12180f', alphaV);
  ctx.beginPath(); ctx.ellipse(p.x, p.y, Math.max(0.6,w*0.5), Math.max(0.5,h), 0,0,TAU); ctx.fill();
}

function drawTreeProp(p){
  const base = project(p.x, GROUND_Y, p.z);
  if (!base) return;
  const s = base.s, f = fogAmount(p.z);
  const col = fogged(p.color, p.z);
  const dark = fogged(shade(p.color,0.72), p.z);
  const h = p.h*s, w = p.w*s;
  if (h < 1.5) return;
  drawShadow(p.x, p.z, p.w*1.1, p.w*1.1, weather().shadow);
  const sway = Math.sin(ambientTime*1.1 + p.seed)*w*0.035 + Math.sin(ambientTime*2.3+p.seed)*w*0.015;
  if (p.type === 'pine'){
    const trunkW = Math.max(1, w*0.11);
    ctx.fillStyle = fogged('#5b4930', p.z);
    ctx.fillRect(base.x-trunkW/2, base.y-h*0.45, trunkW, h*0.45);
    ctx.fillStyle = col;
    for (let i=0;i<4;i++){
      const t = 0.34 + i*0.19;
      const ww = w*(0.62 - i*0.12);
      const yy = base.y - h*(0.4 + i*0.17);
      ctx.beginPath();
      ctx.moveTo(base.x + sway*(0.4+i*0.2), yy - h*0.28);
      ctx.lineTo(base.x - ww/2, yy);
      ctx.lineTo(base.x + ww/2, yy);
      ctx.closePath(); ctx.fill();
    }
    ctx.fillStyle = alpha('#d6e2c8', 0.05*(1-f));
    ctx.beginPath();
    ctx.moveTo(base.x + sway, base.y-h*1.0);
    ctx.lineTo(base.x + w*0.26, base.y-h*0.4);
    ctx.lineTo(base.x + w*0.12, base.y-h*0.4);
    ctx.closePath(); ctx.fill();
  } else {
    const trunkW = Math.max(1, w*0.13);
    ctx.fillStyle = fogged('#57452e', p.z);
    ctx.fillRect(base.x-trunkW/2 + sway*0.2, base.y-h*0.5, trunkW, h*0.5);
    ctx.fillStyle = dark;
    ctx.beginPath(); ctx.ellipse(base.x+sway, base.y-h*0.7, w*0.62, h*0.31, 0,0,TAU); ctx.fill();
    ctx.fillStyle = col;
    ctx.beginPath(); ctx.ellipse(base.x+sway*0.7, base.y-h*0.74, w*0.48, h*0.25, 0,0,TAU); ctx.fill();
    ctx.beginPath(); ctx.ellipse(base.x-w*0.22+sway, base.y-h*0.62, w*0.32, h*0.19, 0,0,TAU); ctx.fill();
    ctx.fillStyle = alpha('#cfe0bd', 0.09*(1-f));
    ctx.beginPath(); ctx.ellipse(base.x-w*0.16+sway, base.y-h*0.82, w*0.24, h*0.1, 0,0,TAU); ctx.fill();
  }
}

function drawBushProp(p){
  const base = project(p.x, GROUND_Y, p.z);
  if (!base) return;
  const w = p.w*base.s, h = p.h*base.s;
  if (h < 1) return;
  drawShadow(p.x,p.z,p.w,p.w*0.8,weather().shadow*0.7);
  const sway = Math.sin(ambientTime*1.5+p.seed)*w*0.03;
  ctx.fillStyle = fogged(shade(p.color,0.82),p.z);
  ctx.beginPath(); ctx.ellipse(base.x+sway,base.y-h*0.42,w*0.52,h*0.55,0,0,TAU); ctx.fill();
  ctx.fillStyle = fogged(p.color,p.z);
  ctx.beginPath(); ctx.ellipse(base.x-w*0.2+sway,base.y-h*0.55,w*0.32,h*0.44,0,0,TAU); ctx.fill();
  ctx.beginPath(); ctx.ellipse(base.x+w*0.22+sway,base.y-h*0.48,w*0.28,h*0.38,0,0,TAU); ctx.fill();
}
function drawRockProp(p){
  const base = project(p.x, GROUND_Y, p.z);
  if (!base) return;
  const w = p.w*base.s, h = p.h*base.s;
  if (h < 1) return;
  drawShadow(p.x,p.z,p.w,p.w*0.7,weather().shadow);
  ctx.fillStyle = fogged(p.color,p.z);
  ctx.beginPath();
  ctx.moveTo(base.x-w*0.5, base.y);
  ctx.lineTo(base.x-w*0.3, base.y-h*0.8);
  ctx.lineTo(base.x+w*0.08, base.y-h);
  ctx.lineTo(base.x+w*0.46, base.y-h*0.55);
  ctx.lineTo(base.x+w*0.5, base.y);
  ctx.closePath(); ctx.fill();
  ctx.fillStyle = alpha('#ffffff',0.10*(1-fogAmount(p.z)));
  ctx.beginPath(); ctx.moveTo(base.x-w*0.3,base.y-h*0.8); ctx.lineTo(base.x+w*0.08,base.y-h); ctx.lineTo(base.x+w*0.02,base.y-h*0.65); ctx.closePath(); ctx.fill();
}
function drawHayProp(p){
  const base = project(p.x, GROUND_Y, p.z);
  if (!base) return;
  const w = p.w*base.s, h = p.h*base.s;
  if (h < 1) return;
  drawShadow(p.x,p.z,p.w,p.w*0.7,weather().shadow);
  const c = fogged(p.color,p.z);
  ctx.fillStyle = c;
  ctx.beginPath();
  ctx.ellipse(base.x, base.y-h*0.5, w*0.5, h*0.5, 0,0,TAU); ctx.fill();
  ctx.fillStyle = alpha('#4e4123',0.3);
  for (let i=1;i<4;i++){ ctx.beginPath(); ctx.ellipse(base.x,base.y-h*(0.2+i*0.18),w*0.35,h*0.08,0,0,TAU); ctx.strokeStyle=alpha('#5b4b27',0.35); ctx.lineWidth=1; ctx.stroke(); }
}
function drawGrassProp(p){
  const base = project(p.x, GROUND_Y, p.z);
  if (!base) return;
  const h = p.h*base.s, w = p.w*base.s;
  if (h < 2) return;
  const sway = Math.sin(ambientTime*2.4+p.seed)*w*0.12;
  ctx.strokeStyle = fogged(p.color,p.z);
  ctx.lineWidth = Math.max(1, w*0.08);
  for (let i=0;i<5;i++){
    const ox = (i-2)*w*0.16;
    ctx.beginPath(); ctx.moveTo(base.x+ox,base.y);
    ctx.quadraticCurveTo(base.x+ox+sway*0.4,base.y-h*0.55,base.x+ox+sway,base.y-h*(0.75+0.1*Math.sin(p.seed+i)));
    ctx.stroke();
  }
}

function drawBuildingProp(p){
  const s0 = project(p.x, GROUND_Y, p.z);
  if (!s0) return;
  const w = p.w, d = p.d, h = p.h, rh = p.roof;
