function drawPoleProp(p){
  const base = project(p.x,GROUND_Y,p.z);
  if (!base) return;
  const s=base.s, h=p.h*s;
  if (h<2) return;
  const col = fogged('#5a4b37',p.z);
  ctx.strokeStyle = col; ctx.lineWidth = Math.max(1,s*0.09);
  ctx.beginPath(); ctx.moveTo(base.x,base.y); ctx.lineTo(base.x,base.y-h); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(base.x-s*1.1,base.y-h*0.88); ctx.lineTo(base.x+s*1.1,base.y-h*0.88); ctx.stroke();
