    }
  }
}

function drawProp(p){
  switch(p.type){
    case 'pine': case 'broad': drawTreeProp(p); break;
    case 'bush': drawBushProp(p); break;
    case 'rock': drawRockProp(p); break;
    case 'hay': drawHayProp(p); break;
    case 'grass': drawGrassProp(p); break;
    case 'building': drawBuildingProp(p); break;
    case 'silo': drawSiloProp(p); break;
    case 'tower': drawTowerProp(p); break;
    case 'antenna': drawAntennaProp(p); break;
    case 'truck': drawTruckProp(p); break;
    case 'fence': drawFenceProp(p); break;
    case 'pole': drawPoleProp(p); break;
  }
}
