+  const wz = o.wind ? o.wind.vz||0 : 0;
+  let t=0, closest=1e9, closestAt=null;
+  while (t<maxT){
+    const rx=vx-wx, ry=vy, rz=vz-wz;
+    const sp=Math.hypot(rx,ry,rz);
