function drawWorldEffects(){
  for (const e of effects){
    const p=project(e.x,e.y,e.z);
    if (!p) continue;
    const t=e.age/e.life;
    if (e.type==='blood'){
      const r=(0.10+t*0.55)*p.s;
      ctx.fillStyle=alpha('#7c2d23', (1-t)*0.55);
      for (let i=0;i<5;i++){
        const a=e.seed+i*1.9;
        ctx.beginPath(); ctx.arc(p.x+Math.cos(a)*r*1.7, p.y+Math.sin(a)*r*1.2, Math.max(0.7,r*0.25),0,TAU); ctx.fill();
      }
      ctx.fillStyle=alpha('#d46952',(1-t)*0.35);
      ctx.beginPath(); ctx.arc(p.x,p.y,Math.max(1,r*0.5),0,TAU); ctx.fill();
    } else {
      const r=(0.16+t*0.75)*p.s;
      const col=currentWeather==='rain'?'#aebbb3':weather().dust;
      ctx.fillStyle=alpha(col,(1-t)*0.42);
      ctx.beginPath(); ctx.ellipse(p.x,p.y,r,r*0.55,0,0,TAU); ctx.fill();
      if (e.type==='splash'){
        ctx.strokeStyle=alpha('#d6e2dc',(1-t)*0.4); ctx.lineWidth=1;
        ctx.beginPath(); ctx.ellipse(p.x,p.y,r*1.4,r*0.25,0,0,TAU); ctx.stroke();
      }
    }
  }
}
function drawMuzzleSmoke(){
  for (const p of smokePuffs){
    const t=p.age/p.life;
    ctx.fillStyle=alpha('#d8d5c4',(1-t)*0.16);
    ctx.beginPath(); ctx.arc(p.x,p.y,p.size*(0.6+t*1.8),0,TAU); ctx.fill();
  }
}
function drawWeatherOverlay(){
  const w=weather();
  // tint / exposure
  if (w.tintA>0){
    ctx.fillStyle=alpha(w.tint,w.tintA);
    ctx.fillRect(0,0,W,H);
  }
  if (w.night>0){
    ctx.fillStyle=alpha('#0a1024', w.night*0.6);
    ctx.fillRect(0,0,W,H);
  }
  // fog bank
  if (currentWeather==='fog'){
    const hy=clamp(horizonY(),-100,H+100);
    const g=ctx.createLinearGradient(0,hy-80,0,hy+260);
    g.addColorStop(0,alpha(w.fog,0.16));
    g.addColorStop(0.4,alpha(w.fog,0.5));
    g.addColorStop(1,alpha(w.fog,0.02));
    ctx.fillStyle=g; ctx.fillRect(0,0,W,H);
    for (let i=0;i<5;i++){
      const bx=((i*317+ambientTime*7)%(W+400))-200;
      const by=hy-30+Math.sin(i*2.3)*34;
      const g2=ctx.createRadialGradient(bx,by,10,bx,by,210);
      g2.addColorStop(0,alpha('#d4dbcd',0.10)); g2.addColorStop(1,alpha('#d4dbcd',0));
      ctx.fillStyle=g2; ctx.fillRect(bx-210,by-120,420,240);
    }
  }
  // rain
  if (w.rain && world.rain){
    ctx.strokeStyle=alpha('#c6d6d4',0.20); ctx.lineWidth=1;
    ctx.beginPath();
    const slant=clamp(mission?mission.wind.vx*0.04:0,-0.8,0.8);
    for (const d of world.rain){
      ctx.moveTo(d.x,d.y); ctx.lineTo(d.x-slant*d.l, d.y-d.l);
    }
    ctx.stroke();
  }
  // lightning
  if (lightning>0){
    ctx.fillStyle=alpha('#e8f0ff', lightning*0.45);
    ctx.fillRect(0,0,W,H);
  }
  if (screenFlash>0){
    ctx.fillStyle=alpha('#ffe2a1', screenFlash*0.25);
    ctx.fillRect(0,0,W,H);
  }
  // near-camera vignette
  const vg=ctx.createRadialGradient(W/2,H/2,H*0.34,W/2,H/2,H*0.9);
  vg.addColorStop(0,'rgba(0,0,0,0)'); vg.addColorStop(1,'rgba(0,0,0,.35)');
  ctx.fillStyle=vg; ctx.fillRect(0,0,W,H);
}
