/* ============================================================
   SCOPE / RETICLE / WEAPON
   ============================================================ */
function drawScopeOverlay(){
  const z=view.zoomT;
  if (z<=0.015) return;
  const cx=W/2, cy=H/2;
  const R=Math.min(W,H)*0.456;
  const a=smooth(0.02,0.62,z);
  ctx.save();
  ctx.beginPath();
  ctx.rect(0,0,W,H);
  ctx.arc(cx,cy,R,0,TAU,true);
  ctx.fillStyle=`rgba(2,5,3,${0.965*a})`;
  ctx.fill();
  ctx.restore();
  // scope glass edge
  const ring=ctx.createRadialGradient(cx,cy,R*0.90,cx,cy,R*1.045);
  ring.addColorStop(0,'rgba(0,0,0,0)');
  ring.addColorStop(0.45,`rgba(0,0,0,${0.28*a})`);
  ring.addColorStop(0.8,`rgba(12,18,12,${0.8*a})`);
  ring.addColorStop(1,'rgba(0,0,0,0)');
  ctx.fillStyle=ring; ctx.beginPath(); ctx.arc(cx,cy,R*1.05,0,TAU); ctx.fill();
  ctx.strokeStyle=alpha('#8aa080',0.16*a); ctx.lineWidth=1.2; ctx.beginPath(); ctx.arc(cx,cy,R,0,TAU); ctx.stroke();
  // glass tint
  ctx.save(); ctx.beginPath(); ctx.arc(cx,cy,R,0,TAU); ctx.clip();
  const glass=ctx.createLinearGradient(cx-R,cy-R,cx+R,cy+R);
  glass.addColorStop(0,'rgba(150,190,170,.035)');
  glass.addColorStop(0.5,'rgba(0,0,0,0)');
  glass.addColorStop(1,'rgba(40,70,50,.06)');
  ctx.fillStyle=glass; ctx.fillRect(cx-R,cy-R,R*2,R*2);
  // lens shadow + dust
  const sh=ctx.createRadialGradient(cx-R*0.45,cy-R*0.5,10,cx-R*0.32,cy-R*0.4,R*1.1);
  sh.addColorStop(0,'rgba(255,255,255,.025)'); sh.addColorStop(0.5,'rgba(0,0,0,0)'); sh.addColorStop(1,'rgba(0,0,0,.28)');
  ctx.fillStyle=sh; ctx.fillRect(cx-R,cy-R,R*2,R*2);
  ctx.fillStyle=alpha('#dce7cf',0.06);
  for (let i=0;i<7;i++){ ctx.beginPath(); ctx.arc(cx-180+((i*137)%360), cy-140+((i*89)%280), 0.7+(i%3)*0.6,0,TAU); ctx.fill(); }
  ctx.restore();
  // reticle
  ctx.save();
  ctx.globalAlpha=a;
  const f=focal();
  const milPx=f*0.001;
  const ret=alpha('#c8e0b4',0.82);
  ctx.strokeStyle=ret; ctx.fillStyle=ret; ctx.lineWidth=1.05;
  const armX=Math.min(R*0.62,190), armY=Math.min(R*0.70,235);
  // thin cross
  ctx.beginPath();
  ctx.moveTo(cx-armX,cy); ctx.lineTo(cx-14,cy);
  ctx.moveTo(cx+14,cy); ctx.lineTo(cx+armX,cy);
  ctx.moveTo(cx,cy-armY); ctx.lineTo(cx,cy-13);
  ctx.moveTo(cx,cy+13); ctx.lineTo(cx,cy+armY);
  ctx.stroke();
  // duplex posts
  ctx.lineWidth=2.6;
  ctx.beginPath();
  ctx.moveTo(cx-armX,cy); ctx.lineTo(cx-armX+44,cy);
  ctx.moveTo(cx+armX,cy); ctx.lineTo(cx+armX-44,cy);
  ctx.moveTo(cx,cy+armY); ctx.lineTo(cx,cy+armY-48);
  ctx.moveTo(cx,cy-armY); ctx.lineTo(cx,cy-armY+36);
  ctx.stroke();
  // mil dots
  ctx.lineWidth=1;
  ctx.font='8px ui-monospace,monospace';
  ctx.textAlign='center';
  for (let i=1;i<=10;i++){
    const yy=cy+milPx*i;
    if (yy>cy+armY-12) break;
    ctx.beginPath(); ctx.arc(cx,yy, i%2===0?1.35:0.85,0,TAU); ctx.fill();
    if (i%2===0 && i<=8){ ctx.fillStyle=alpha('#c8e0b4',0.58); ctx.fillText(String(i), cx+12, yy+3); ctx.fillStyle=ret; }
    if (i<=7){
      for (const side of [-1,1]){
        const xx=cx+milPx*i*side;
        if (Math.abs(xx-cx)<armX-8){ ctx.beginPath(); ctx.arc(xx,cy,0.85,0,TAU); ctx.fill(); }
      }
    }
  }
  // center dot
  ctx.beginPath(); ctx.arc(cx,cy,1.6,0,TAU); ctx.fill();
  // scope tick ring
  ctx.strokeStyle=alpha('#c8e0b4',0.28);
  for (let i=0;i<24;i++){
    const ang=i/24*TAU;
    const r0=R*0.965, r1=R*(i%6===0?0.925:0.945);
    ctx.beginPath(); ctx.moveTo(cx+Math.cos(ang)*r0,cy+Math.sin(ang)*r0); ctx.lineTo(cx+Math.cos(ang)*r1,cy+Math.sin(ang)*r1); ctx.stroke();
  }
  const lo=getLoadout();
  ctx.fillStyle=alpha('#c8e0b4',0.55);
  ctx.font='9px ui-monospace,monospace';
  ctx.fillText(`${lo.zoom.toFixed(1)}×  ·  ${(lo.fov*180/Math.PI).toFixed(1)}°`, cx, cy+R*0.80);
  ctx.fillStyle=alpha('#c8e0b4',0.38);
  ctx.font='7px ui-monospace,monospace';
  ctx.fillText('MIL-DOT · ILLUMINATED', cx, cy-R*0.80);
  // target lock bracket
  if (scope && scope.range.time>1.5 && scope.range.targetId>=0 && mission){
    const t=mission.targets.find(q=>q.id===scope.range.targetId);
    if (t && t.alive){
      const p=project(t.x, targetChestY(t), t.z);
      if (p){
        const s=project(t.x, t.groundY+targetHeight(t), t.z);
        const foot=project(t.x,t.groundY,t.z);
        const h = s&&foot ? Math.abs(foot.y-s.y) : 30;
        const w = Math.max(12, h*0.42);
        const pad=6;
        const x0=p.x-w/2-pad, x1=p.x+w/2+pad, y0=p.y-h/2-pad, y1=p.y+h/2+pad;
        const corner=8;
        ctx.strokeStyle=alpha('#d9e8c4',0.58); ctx.lineWidth=1;
        ctx.beginPath();
        ctx.moveTo(x0,y0+corner); ctx.lineTo(x0,y0); ctx.lineTo(x0+corner,y0);
        ctx.moveTo(x1-corner,y0); ctx.lineTo(x1,y0); ctx.lineTo(x1,y0+corner);
        ctx.moveTo(x0,y1-corner); ctx.lineTo(x0,y1); ctx.lineTo(x0+corner,y1);
        ctx.moveTo(x1-corner,y1); ctx.lineTo(x1,y1); ctx.lineTo(x1,y1-corner);
        ctx.stroke();
        ctx.fillStyle=alpha('#d9e8c4',0.68);
        ctx.font='8px ui-monospace,monospace'; ctx.textAlign='left';
        ctx.fillText(`${Math.round(scope.range.dist)} M`, x1+6, y0+3);
      }
    }
  }
  ctx.restore();
  // flash
  if (screenFlash>0.35){
    ctx.fillStyle=`rgba(255,238,196,${Math.min(0.35,(screenFlash-0.35)*0.6)})`;
    ctx.beginPath(); ctx.arc(cx,cy,R,0,TAU); ctx.fill();
  }
}

function drawWeapon(){
  const z=view.zoomT;
  if (z>0.62) return;
  const a=1-smooth(0.05,0.62,z);
  const swayX=view.swayYaw*2600;
  const swayY=view.swayPitch*1800;
  const bob=Math.sin(ambientTime*1.1)*2;
  ctx.save();
  ctx.globalAlpha=a;
  ctx.translate(W*0.72+swayX, H*0.79+swayY+bob);
  ctx.rotate(-0.10);
  // stock
  ctx.fillStyle='#2a2d27';
  ctx.beginPath(); ctx.moveTo(250,260); ctx.lineTo(330,310); ctx.lineTo(300,350); ctx.lineTo(205,300); ctx.closePath(); ctx.fill();
  ctx.fillStyle='#4a4c3c';
  ctx.beginPath(); ctx.moveTo(250,258); ctx.lineTo(308,296); ctx.lineTo(292,312); ctx.lineTo(234,275); ctx.closePath(); ctx.fill();
  // receiver
  ctx.fillStyle='#1e211d';
  ctx.fillRect(-30,215,175,50);
  ctx.fillStyle='#383d34';
  ctx.fillRect(-22,219,150,13);
  // barrel
  ctx.fillStyle='#242722';
  ctx.fillRect(-255,228,235,16);
  ctx.fillStyle='#454a3e';
  ctx.fillRect(-255,231,225,4);
  // muzzle brake
  ctx.fillStyle='#161815';
  ctx.fillRect(-288,223,42,25);
  // bolt handle
  ctx.fillStyle='#5f6352';
  ctx.fillRect(55,247,44,8);
  ctx.beginPath(); ctx.arc(104,251,7,0,TAU); ctx.fill();
  // scope
  ctx.fillStyle='#151814';
  ctx.fillRect(-12,177,145,25);
  ctx.fillStyle='#0b0d0b';
  ctx.beginPath(); ctx.ellipse(140,189,17,22,0,0,TAU); ctx.fill();
  ctx.strokeStyle='rgba(200,220,190,.18)'; ctx.lineWidth=1;
  ctx.beginPath(); ctx.ellipse(140,189,13,17,0,0,TAU); ctx.stroke();
  // rings
  ctx.fillStyle='#33372f';
  ctx.fillRect(15,175,10,34); ctx.fillRect(95,175,10,34);
  // magazine
  ctx.fillStyle='#1a1d18';
  ctx.beginPath(); ctx.moveTo(30,262); ctx.lineTo(90,262); ctx.lineTo(80,325); ctx.lineTo(42,325); ctx.closePath(); ctx.fill();
  // hand
  ctx.fillStyle='#4b3a2c';
  ctx.beginPath(); ctx.ellipse(150,268,28,18,-0.25,0,TAU); ctx.fill();
  ctx.fillStyle='#5b4634';
  ctx.beginPath(); ctx.ellipse(152,262,20,11,-0.25,0,TAU); ctx.fill();
  // muzzle flash
  if (screenFlash>0.45){
    const mf=screenFlash;
    const gg=ctx.createRadialGradient(-290,235,1,-290,235,75);
    gg.addColorStop(0,`rgba(255,246,200,${0.9*mf})`);
    gg.addColorStop(0.25,`rgba(255,196,90,${0.65*mf})`);
    gg.addColorStop(1,'rgba(255,160,40,0)');
    ctx.fillStyle=gg; ctx.beginPath(); ctx.arc(-290,235,75,0,TAU); ctx.fill();
    ctx.fillStyle=`rgba(255,236,170,${0.8*mf})`;
    ctx.beginPath();
    for (let i=0;i<9;i++){ const ang=i/9*TAU; const rr=i%2?14:48; ctx.lineTo(-290+Math.cos(ang)*rr,235+Math.sin(ang)*rr); }
    ctx.closePath(); ctx.fill();
  }
  ctx.restore();
  ctx.globalAlpha=1;
}

function drawHipCrosshair(){
  if (view.zoomT>0.18) return;
  const cx=W/2, cy=H/2, a=1-view.zoomT/0.18;
  ctx.save(); ctx.globalAlpha=a;
  ctx.strokeStyle='rgba(220,232,200,.55)'; ctx.lineWidth=1;
  ctx.beginPath();
  ctx.moveTo(cx-18,cy); ctx.lineTo(cx-7,cy);
  ctx.moveTo(cx+7,cy); ctx.lineTo(cx+18,cy);
  ctx.moveTo(cx,cy-18); ctx.lineTo(cx,cy-7);
  ctx.moveTo(cx,cy+7); ctx.lineTo(cx,cy+18);
  ctx.stroke();
  ctx.fillStyle='rgba(229,180,91,.75)';
  ctx.beginPath(); ctx.arc(cx,cy,1.4,0,TAU); ctx.fill();
  ctx.restore();
}
</script>

