/* ============================================================
   HUD
   ============================================================ */
function setText(id,txt){ const el=$(id); if (el && el.textContent!==txt) el.textContent=txt; }
function updateHUD(force){
  if (!mission || !scope) return;
  const now=ambientTime;
  if (!force && now-lastHudUpdate<0.07) return;
  lastHudUpdate=now;
  const lo=getLoadout();
  setText('hudOp',String(mission.op).padStart(2,'0'));
  setText('hudOpName',mission.cfg.name);
  setText('hudTargets',`${mission.kills} / ${mission.targets.length}`);
  setText('hudTimer',fmtTime(mission.timeLeft));
  $('hudTimer').classList.toggle('warn',mission.timeLeft<45);
  setText('hudRifle',lo.rifle.name);
  setText('hudCal',lo.rifle.cal);
  setText('hudAmmoName',lo.ammo.name);
  setText('hudAmmo',String(scope.ammo));
  setText('hudMag',String(lo.rifle.mag));
  const rl=$('reloadHint');
  rl.classList.toggle('on', scope.ammo<=0 && scope.reload<=0);
  $('reloadFill').style.transform=`scaleX(${scope.reload>0 ? 1-scope.reload/lo.rifle.reload : (scope.ammo<=0?0:1)})`;
  setText('breathPct',String(Math.round(scope.breath)));
  $('breathFill').style.transform=`scaleX(${scope.breath/100})`;
  setText('stanceHint',scope.holding?'HOLDING · STEADY':'SHIFT STEADY');
  setText('controlHint',gamepadState.index>=0 ? 'RT FIRE · LT SCOPE · A RELOAD · RB RANGE' : 'Z SCOPE · F RANGE · R RELOAD · T SOLVE');
  const w=weather();
  setText('hudWeather',w.label);
  setText('hudVis',`VIS ${(w.vis/1000).toFixed(1)} KM`);
  const wi=mission.wind;
  const right=wi.vx*Math.cos(view.yaw)-wi.vz*Math.sin(view.yaw);
  const fwd=wi.vx*Math.sin(view.yaw)+wi.vz*Math.cos(view.yaw);
  const deg=Math.atan2(-fwd,right)*180/Math.PI;
  $('windArrow').textContent='➤';
  $('windArrow').style.transform=`rotate(${deg}deg)`;
  setText('windSpeed',fmt1(wi.speed));
  let dir='CALM';
  if (wi.speed>0.4){
    if (Math.abs(right)>Math.abs(fwd)) dir=right>0?'CROSSING R':'CROSSING L';
    else dir=fwd>0?'TAILWIND':'HEADWIND';
  }
  setText('windDir',dir);
  setText('hudZero',`ZERO ${scope.zeroRange} M`);
  if (scope.range.dist>0){
    setText('hudRange',`${Math.round(scope.range.dist)} M`);
    const h=predictHold(scope.range.dist, mission.wind);
    const hs=Math.abs(h.hold)<0.05?'0.0':fmt1(Math.abs(h.hold));
    const ds=Math.abs(h.drift)<0.05?'0.0':fmt1(Math.abs(h.drift));
    setText('hudHold',`${h.hold>=0?'↑':'↓'} ${hs} MIL`);
    setText('hudDrift',`${h.drift>=0?'←':'→'} ${ds} MIL`);
  } else {
    setText('hudRange','--- M'); setText('hudHold','—'); setText('hudDrift','—');
  }
  setText('hudSolve', !career.computer ? 'MANUAL HOLD' : scope.solution.active ? 'SOLUTION LOCKED' : 'T AUTO-SOLVE');
  $('scopePrompt').classList.toggle('on', state==='mission' && !pointerLocked && gamepadState.index<0);
}
function clearHudFeed(){ feedItems=[]; renderFeed(); }

/* ============================================================
   MISSION FLOW
   ============================================================ */
function newScope(){
  const lo=getLoadout();
  return {
    zeroRange:200, zeroAngle:0, ammo:lo.rifle.mag, breath:100, holding:false,
    scoped:false, cycle:0, reload:0, bolt:0,
    range:{dist:0,time:0,targetId:-1,exact:false,cool:0,tx:0,tz:0},
    solution:{elevMil:0,windMil:0,active:false,time:0}
  };
}
function tryLock(){
  if (gamepadState.index>=0) return;
  try { canvas.requestPointerLock && canvas.requestPointerLock(); } catch(e){}
}
function deployMission(opNum){
  const cfg=opConfig(opNum);
  currentWeather=cfg.weather;
  mission=createMission(opNum);
  scope=newScope();
  const lo=getLoadout();
  scope.zeroAngle=solveZeroAngle(lo.mv,lo.bc,scope.zeroRange);
  aim.yaw=0; aim.pitch=-0.07;
  view.zoomT=0; view.recoilPitch=0; view.recoilYaw=0; view.rvP=0; view.rvY=0; view.shake=0;
  bullets=[]; effects=[]; smokePuffs.length=0; floaters=[]; clearHudFeed();
  timeScale=1; slowmoT=0; screenFlash=0; lightning=0; lightningTimer=12;
  state='mission';
  document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active'));
  $('hud').classList.add('on');
  updateHUD(true);
  showBanner('OPERATION '+String(opNum).padStart(2,'0'),cfg.name+' · '+cfg.weather.toUpperCase(),2400);
  setTimeout(()=>{ if (state==='mission') addFeed('CONTACTS IN SECTOR · USE F TO RANGE',''); },600);
  setTimeout(()=>{ if (state==='mission') addFeed(career.computer?'T COMPUTES A FIRING SOLUTION':'MIL-DOT HOLDS · ZERO WITH [ ]',''); },2600);
  initAudio(); startAmbient();
  tryLock();
}
function finishMission(success){
  if (!mission || mission.ended) return;
  mission.ended=true; mission.completed=success;
  state='debrief';
  if (document.pointerLockElement) document.exitPointerLock();
  $('hud').classList.remove('on');
  const cfg=mission.cfg;
  const lo=getLoadout();
  let killCredits=0;
  for (const k of mission.killLog) killCredits += Math.round(90 + k.dist/10 + (k.head?100:0));
  if (!success) killCredits=Math.round(killCredits*0.5);
  const acc=mission.shots>0?mission.kills/mission.shots:0;
  const completion=success?Math.round(220+cfg.targets*45+mission.op*35):0;
  const accBonus=success?(acc>=0.7?220:acc>=0.5?110:0):0;
  const speedBonus=success?Math.round(mission.timeLeft*1.5):0;
  const subBonus=lo.ammo.sub?Math.round((killCredits+completion+accBonus+speedBonus)*0.25):0;
  const total=killCredits+completion+accBonus+speedBonus+subBonus;
  career.credits=Math.max(0,career.credits+total);
  career.totals.kills+=mission.kills; career.totals.shots+=mission.shots;
  career.totals.heads+=mission.headshots; career.totals.best=Math.max(career.totals.best,mission.best);
  if (success){
    career.totals.ops++;
    career.op=Math.max(career.op,mission.op+1);
  }
  saveCareer();
  lastDebrief={success,total,killCredits,completion,accBonus,speedBonus,subBonus,acc};
  populateDebrief();
  $('screen-debrief').classList.add('active');
  sfx(success?'complete':'fail');
}
let lastDebrief=null;
function populateDebrief(){
  if (!mission || !lastDebrief) return;
  const d=lastDebrief, cfg=mission.cfg;
  $('debriefKicker').textContent=d.success?'OPERATION COMPLETE':'OPERATION FAILED';
  $('debriefKicker').classList.toggle('fail',!d.success);
  $('debriefTitle').textContent=cfg.name;
  $('debriefSub').textContent=`SECTOR IRON VALLEY · ${WEATHER[cfg.weather].label} · OP ${String(mission.op).padStart(2,'0')}`;
  $('dbKills').innerHTML=`${mission.kills}<small>/${mission.targets.length}</small>`;
  $('dbAcc').innerHTML=`${Math.round(d.acc*100)}<small>%</small>`;
  $('dbLong').innerHTML=`${Math.round(mission.best)}<small>m</small>`;
  $('dbHeads').textContent=String(mission.headshots);
  const rows=[
    ['ELIMINATIONS', d.killCredits],
    ['COMPLETION BONUS', d.completion],
    ['ACCURACY BONUS', d.accBonus],
    ['TIME BONUS', d.speedBonus]
  ];
  if (d.subBonus) rows.push(['SUBSONIC BONUS', d.subBonus]);
  $('rewardList').innerHTML=rows.filter(r=>r[1]>0).map(r=>`<div class="reward-line"><span>${r[0]}</span><span>+${fmtInt(r[1])} CR</span></div>`).join('')
    +`<div class="reward-line total"><span>TOTAL CREDITS</span><span>+${fmtInt(d.total)} CR</span></div>`;
  const nextOp=career.op;
  const nextCfg=opConfig(nextOp);
  const nextLabel=d.success?`NEXT · OP ${String(nextOp).padStart(2,'0')} ${nextCfg.name}`:'REDEPLOY OPERATION';
  $('debriefActions').innerHTML=`
    <button class="btn primary" id="btnDebriefNext">${nextLabel}</button>
    <button class="btn" id="btnDebriefArmory">ARMORY</button>
    <button class="btn ghost" id="btnDebriefTitle">TITLE</button>`;
  $('btnDebriefNext').onclick=()=>{ if(d.success){ showBriefing(); } else { deployMission(mission.op); } };
  $('btnDebriefArmory').onclick=()=>{ armoryReturn='debrief'; showArmory(); };
  $('btnDebriefTitle').onclick=()=>showTitle();
}

