function drawBriefMap(opNum,cfg){
  const c=$('briefMap'), g=c.getContext('2d');
  const w=c.width, h=c.height;
  const rnd=mulberry32(0x51a7 ^ (opNum*7717));
  g.clearRect(0,0,w,h);
  g.fillStyle='#0a130c'; g.fillRect(0,0,w,h);
  // grid
  g.strokeStyle='rgba(145,170,130,.10)'; g.lineWidth=1;
  for (let x=0;x<w;x+=26){ g.beginPath(); g.moveTo(x,0); g.lineTo(x,h); g.stroke(); }
  for (let y=0;y<h;y+=26){ g.beginPath(); g.moveTo(0,y); g.lineTo(w,y); g.stroke(); }
  // river
  g.strokeStyle='rgba(103,151,150,.5)'; g.lineWidth=7;
  g.beginPath(); g.moveTo(120,0);
  for (let y=0;y<=h;y+=20) g.lineTo(120+40*Math.sin(y*0.023+1)+8*Math.sin(y*0.07),y);
  g.stroke();
  g.strokeStyle='rgba(170,200,190,.25)'; g.lineWidth=1.5; g.stroke();
  // road
  g.strokeStyle='rgba(180,160,110,.38)'; g.lineWidth=2;
  g.beginPath(); g.moveTo(30,h); g.quadraticCurveTo(260,170,500,30); g.stroke();
  // contours
  for (let i=0;i<11;i++){
    const cx=20+rnd()*w, cy=20+rnd()*h, rx=30+rnd()*90, ry=14+rnd()*45, rot=rnd()*Math.PI;
    g.strokeStyle=`rgba(133,157,109,${0.10+rnd()*0.10})`; g.lineWidth=1;
    g.beginPath(); g.ellipse(cx,cy,rx,ry,rot,0,TAU); g.stroke();
    if (rnd()>0.35){ g.beginPath(); g.ellipse(cx,cy,rx*0.65,ry*0.62,rot,0,TAU); g.stroke(); }
  }
  // target sectors (approximate)
  const n=Math.min(cfg.targets,8);
  for (let i=0;i<n;i++){
    const tx=250+ (i-(n-1)/2)*34 + (rnd()-0.5)*26;
    const ty=80 + rnd()*130;
    g.strokeStyle='rgba(220,104,80,.7)'; g.lineWidth=1;
    g.beginPath(); g.moveTo(tx,ty-5); g.lineTo(tx+5,ty+4); g.lineTo(tx-5,ty+4); g.closePath(); g.stroke();
    if (i===0){ g.strokeStyle='rgba(220,104,80,.35)'; g.beginPath(); g.arc(tx,ty,12,0,TAU); g.stroke(); }
  }
  // observer position
  g.fillStyle='#e5b45b'; g.beginPath(); g.arc(56,238,4,0,TAU); g.fill();
  g.strokeStyle='rgba(229,180,91,.5)'; g.beginPath(); g.arc(56,238,10,0,TAU); g.stroke();
  g.fillStyle='rgba(211,225,194,.6)'; g.font='8px ui-monospace,monospace';
  g.fillText('OBSERVER',70,241);
  g.fillText('SECTOR 7',24,26);
  g.fillStyle='rgba(220,104,80,.85)'; g.fillText('HOSTILE',250,60);
  g.fillStyle='rgba(140,170,130,.4)'; g.font='7px ui-monospace,monospace';
  g.fillText('APPROACH',360,250);
}

/* ============================================================
   ARMORY
   ============================================================ */
function showArmory(){
  state='armory'; hideScreens(); $('screen-armory').classList.add('active'); $('hud').classList.remove('on');
  armorySel=career.rifle;
  renderArmory();
  $('btnArmoryClose').onclick=()=>{
    if (armoryReturn==='briefing') showBriefing();
    else if (armoryReturn==='debrief' && lastDebrief){ state='debrief'; hideScreens(); $('screen-debrief').classList.add('active'); populateDebrief(); }
    else showTitle();
  };
}
function statBar(label, value, max, display){
  const p=clamp(value/max,0,1)*100;
  return `<div class="statline"><span>${label}</span><div class="statbar"><i style="width:${p}%"></i></div><b>${display}</b></div>`;
}
function renderArmory(){
  $('armCredits').textContent=fmtInt(career.credits);
  $('armRifleCount').textContent=`${career.ownedRifles.length} / ${RIFLES.length}`;
  $('rifleList').innerHTML=RIFLES.map(r=>{
    const owned=career.ownedRifles.includes(r.id);
    const sel=r.id===armorySel;
    const eq=r.id===career.rifle;
    return `<div class="rifle-item ${sel?'sel':''} ${owned?'':'locked'} ${eq?'selected-rifle':''}" data-rifle="${r.id}">
      <div class="rname"><span>${r.name}</span>${!owned?`<em>T${r.tier}</em>`:''}</div>
      <div class="rsub">${r.cal} · ${r.mag} RD · ${(r.mv).toFixed(0)} M/S</div>
      ${!owned?`<div class="rprice">${fmtInt(r.cost)} CR</div>`:''}
    </div>`;
  }).join('');
  const r=RIFLE_BY_ID[armorySel];
  const owned=career.ownedRifles.includes(r.id);
  const up=career.upgrades[r.id]||{barrel:0,optic:0,stock:0,trigger:0};
  const mv=r.mv*(1+0.04*(up.barrel||0));
  const zoom=60/r.fov*Math.pow(1.08,up.optic||0);
  const upgrades=UPGRADES.map(u=>{
    const lvl=up[u.id]||0;
    const maxed=lvl>=u.max;
    const cost=maxed?0:u.costs[lvl];
    const can=owned&&!maxed&&career.credits>=cost;
    return `<div class="upgrade-row">
      <div class="un">${u.name}<small>${u.desc}</small></div>
      <div class="pips">${Array.from({length:u.max},(_,i)=>`<i class="${i<lvl?'on':''}"></i>`).join('')}</div>
      <button class="upbuy" data-upgrade="${u.id}" ${can?'':'disabled'}>${maxed?'MAX':fmtInt(cost)}</button>
    </div>`;
  }).join('');
  $('rifleDetail').innerHTML=`
    <div class="dname">${r.name}</div>
    <div class="dcal">${r.cal} · TIER ${r.tier}</div>
    <div class="ddesc">${r.desc}</div>
    ${statBar('VELOCITY',mv,1000,Math.round(mv)+' m/s')}
    ${statBar('BALLISTIC',r.bc,0.82,r.bc.toFixed(2)+' BC')}
    ${statBar('MAGNIFICATION',zoom,13,zoom.toFixed(1)+'×')}
    ${statBar('STABILITY',1/r.sway,1.9,(1/r.sway).toFixed(2))}
    ${statBar('RECOIL',3-r.recoil,2.6,(3-r.recoil).toFixed(2))}
    ${statBar('CAPACITY',r.mag,12,r.mag+' rd')}
    ${statBar('RELOAD',4.6-r.reload,2.4,(4.6-r.reload).toFixed(2))}
    ${!owned?`<div style="margin-top:14px"><button class="btn primary" id="btnBuyRifle" ${career.credits>=r.cost?'':'disabled'}>ACQUIRE · ${fmtInt(r.cost)} CR</button></div>`:''}
    <div class="upgrade-row" style="border-top:1px solid var(--line2);margin-top:12px;padding-top:10px"><div class="un" style="color:var(--amber2)">PLATFORM UPGRADES<small>PER-RIFLE · CREDITS SPENT ARE PERMANENT</small></div></div>
    ${upgrades}
    <div class="comp-card">
      <div class="ct">BALLISTIC COMPUTER<small>Unlocks T · computes elevation and windage to the ranged contact.</small></div>
      <button class="upbuy" id="btnBuyComputer" ${career.computer?'disabled':''}>${career.computer?'INSTALLED':fmtInt(2400)+' CR'}</button>
    </div>`;
  $('ammoList').innerHTML=AMMO.map(a=>{
    const own=career.ownedAmmo.includes(a.id);
    const sel=career.ammo===a.id;
    return `<div class="ammo-item ${sel?'sel':''} ${own?'':'locked'}" data-ammo="${a.id}">
      <div class="an"><span>${a.name}</span>${sel?'<em>LOADED</em>':own?'<em>OWNED</em>':''}</div>
      <div class="as">${a.desc}</div>
      ${!own?`<span class="ap">${fmtInt(a.cost)} CR</span>`:''}
    </div>`;
  }).join('');
  // listeners
  document.querySelectorAll('[data-rifle]').forEach(el=>el.onclick=()=>{ armorySel=el.dataset.rifle; sfx('click'); renderArmory(); });
  document.querySelectorAll('[data-ammo]').forEach(el=>el.onclick=()=>{
    const id=el.dataset.ammo;
    if (career.ownedAmmo.includes(id)){ career.ammo=id; saveCareer(); sfx('click'); renderArmory(); }
    else { buyAmmo(id); }
  });
  document.querySelectorAll('[data-upgrade]').forEach(el=>el.onclick=()=>buyUpgrade(armorySel,el.dataset.upgrade));
  const br=$('btnBuyRifle'); if (br) br.onclick=buySelectedRifle;
  const bc=$('btnBuyComputer');
  if (bc) bc.onclick=()=>{
    if (career.computer||career.credits<2400) return;
    career.credits-=2400; career.computer=true; saveCareer(); sfx('buy'); renderArmory();
  };
}
function buySelectedRifle(){
  const r=RIFLE_BY_ID[armorySel];
  if (!r||career.ownedRifles.includes(r.id)||career.credits<r.cost) return;
  career.credits-=r.cost; career.ownedRifles.push(r.id); career.rifle=r.id;
  if (!career.upgrades[r.id]) career.upgrades[r.id]={barrel:0,optic:0,stock:0,trigger:0};
  saveCareer(); sfx('buy'); renderArmory();
}
function buyAmmo(id){
  const a=AMMO_BY_ID[id];
  if (!a||career.ownedAmmo.includes(id)||career.credits<a.cost) return;
  career.credits-=a.cost; career.ownedAmmo.push(id); career.ammo=id;
  saveCareer(); sfx('buy'); renderArmory();
}
function buyUpgrade(rifleId,upId){
  const r=RIFLE_BY_ID[rifleId];
  if (!r||!career.ownedRifles.includes(rifleId)) return;
  const u=UPGRADES.find(x=>x.id===upId);
  if (!u) return;
  const up=career.upgrades[rifleId]||{barrel:0,optic:0,stock:0,trigger:0};
  const lvl=up[upId]||0;
  if (lvl>=u.max) return;
  const cost=u.costs[lvl];
  if (career.credits<cost) return;
  career.credits-=cost; up[upId]=lvl+1; career.upgrades[rifleId]=up;
  saveCareer(); sfx('buy'); renderArmory();
}

/* ============================================================
   PAUSE
   ============================================================ */
function pauseGame(){
  if (state!=='mission') return;
  state='paused';
  hideScreens(); $('screen-pause').classList.add('active');
  $('pauseSub').textContent=`OPERATION ${String(mission.op).padStart(2,'0')} · ${mission.cfg.name}`;
  if (document.pointerLockElement) document.exitPointerLock();
  $('btnResume').onclick=resumeGame;
  $('btnRestart').onclick=()=>{ hideScreens(); deployMission(mission.op); };
  $('btnAbandon').onclick=()=>{ hideScreens(); showTitle(); };
  $('btnMute').textContent='SOUND: '+(muted?'OFF':'ON');
  $('btnMute').onclick=()=>{ muted=!muted; career.settings.mute=muted; saveCareer(); updateMute(); $('btnMute').textContent='SOUND: '+(muted?'OFF':'ON'); };
}
function resumeGame(){
  if (state!=='paused') return;
  state='mission'; hideScreens(); tryLock();
}
</script>

