+  setText('hudRifle',lo.rifle.name);
+  setText('hudCal',lo.rifle.cal);
+  setText('hudAmmoName',lo.ammo.name);
+  setText('hudAmmo',String(scope.ammo));
+  setText('hudMag',String(lo.rifle.mag));
+  const rl=$('reloadHint');
+  rl.classList.toggle('on', scope.ammo<=0 && scope.reload<=0);
+  $('reloadFill').style.transform=`scaleX(${scope.reload>0 ? 1-scope.reload/lo.rifle.reload : (scope.ammo<=0?0:1)})`;
+  setText('breathPct',String(Math.round(scope.breath)));
+  $('breathFill').style.transform=`scaleX(${scope.breath/100})`;
+  setText('stanceHint',scope.holding?'HOLDING · STEADY':'SHIFT STEADY');
+  setText('controlHint',gamepadState.index>=0 ? 'RT FIRE · LT SCOPE · A RELOAD · RB RANGE' : 'Z SCOPE · F RANGE · R RELOAD · T SOLVE');
+  const w=weather();
+  setText('hudWeather',w.label);
+  setText('hudVis',`VIS ${(w.vis/1000).toFixed(1)} KM`);
+  const wi=mission.wind;
+  const right=wi.vx*Math.cos(view.yaw)-wi.vz*Math.sin(view.yaw);
+  const fwd=wi.vx*Math.sin(view.yaw)+wi.vz*Math.cos(view.yaw);
+  const deg=Math.atan2(-fwd,right)*180/Math.PI;
+  $('windArrow').textContent='➤';
+  $('windArrow').style.transform=`rotate(${deg}deg)`;
+  setText('windSpeed',fmt1(wi.speed));
+  let dir='CALM';
+  if (wi.speed>0.4){
+    if (Math.abs(right)>Math.abs(fwd)) dir=right>0?'CROSSING R':'CROSSING L';
+    else dir=fwd>0?'TAILWIND':'HEADWIND';
+  }
+  setText('windDir',dir);
+  setText('hudZero',`ZERO ${scope.zeroRange} M`);
+  if (scope.range.dist>0){
+    setText('hudRange',`${Math.round(scope.range.dist)} M`);
+    const h=predictHold(scope.range.dist, mission.wind);
+    const hs=Math.abs(h.hold)<0.05?'0.0':fmt1(Math.abs(h.hold));
+    const ds=Math.abs(h.drift)<0.05?'0.0':fmt1(Math.abs(h.drift));
+    setText('hudHold',`${h.hold>=0?'↑':'↓'} ${hs} MIL`);
+    setText('hudDrift',`${h.drift>=0?'←':'→'} ${ds} MIL`);
+  } else {
+    setText('hudRange','--- M'); setText('hudHold','—'); setText('hudDrift','—');
+  }
+  setText('hudSolve', !career.computer ? 'MANUAL HOLD' : scope.solution.active ? 'SOLUTION LOCKED' : 'T AUTO-SOLVE');
+  $('scopePrompt').classList.toggle('on', state==='mission' && !pointerLocked && gamepadState.index<0);
+}
+function clearHudFeed(){ feedItems=[]; renderFeed(); }
+
+/* ============================================================
+   MISSION FLOW
+   ============================================================ */
+function newScope(){
+  const lo=getLoadout();
+  return {
+    zeroRange:200, zeroAngle:0, ammo:lo.rifle.mag, breath:100, holding:false,
+    scoped:false, cycle:0, reload:0, bolt:0,
+    range:{dist:0,time:0,targetId:-1,exact:false,cool:0,tx:0,tz:0},
+    solution:{elevMil:0,windMil:0,active:false,time:0}
+  };
+}
+function tryLock(){
+  if (gamepadState.index>=0) return;
+  try { canvas.requestPointerLock && canvas.requestPointerLock(); } catch(e){}
+}
+function deployMission(opNum){
+  const cfg=opConfig(opNum);
+  currentWeather=cfg.weather;
+  mission=createMission(opNum);
+  scope=newScope();
+  const lo=getLoadout();
+  scope.zeroAngle=solveZeroAngle(lo.mv,lo.bc,scope.zeroRange);
+  aim.yaw=0; aim.pitch=-0.07;
+  view.zoomT=0; view.recoilPitch=0; view.recoilYaw=0; view.rvP=0; view.rvY=0; view.shake=0;
+  bullets=[]; effects=[]; smokePuffs.length=0; floaters=[]; clearHudFeed();
+  timeScale=1; slowmoT=0; screenFlash=0; lightning=0; lightningTimer=12;
+  state='mission';
+  document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active'));
+  $('hud').classList.add('on');
+  updateHUD(true);
+  showBanner('OPERATION '+String(opNum).padStart(2,'0'),cfg.name+' · '+cfg.weather.toUpperCase(),2400);
+  setTimeout(()=>{ if (state==='mission') addFeed('CONTACTS IN SECTOR · USE F TO RANGE',''); },600);
+  setTimeout(()=>{ if (state==='mission') addFeed(career.computer?'T COMPUTES A FIRING SOLUTION':'MIL-DOT HOLDS · ZERO WITH [ ]',''); },2600);
+  initAudio(); startAmbient();
+  tryLock();
+}
+function finishMission(success){
+  if (!mission || mission.ended) return;
+  mission.ended=true; mission.completed=success;
+  state='debrief';
+  if (document.pointerLockElement) document.exitPointerLock();
+  $('hud').classList.remove('on');
+  const cfg=mission.cfg;
+  const lo=getLoadout();
+  let killCredits=0;
+  for (const k of mission.killLog) killCredits += Math.round(90 + k.dist/10 + (k.head?100:0));
+  if (!success) killCredits=Math.round(killCredits*0.5);
+  const acc=mission.shots>0?mission.kills/mission.shots:0;
+  const completion=success?Math.round(220+cfg.targets*45+mission.op*35):0;
+  const accBonus=success?(acc>=0.7?220:acc>=0.5?110:0):0;
+  const speedBonus=success?Math.round(mission.timeLeft*1.5):0;
+  const subBonus=lo.ammo.sub?Math.round((killCredits+completion+accBonus+speedBonus)*0.25):0;
+  const total=killCredits+completion+accBonus+speedBonus+subBonus;
+  career.credits=Math.max(0,career.credits+total);
+  career.totals.kills+=mission.kills; career.totals.shots+=mission.shots;
+  career.totals.heads+=mission.headshots; career.totals.best=Math.max(career.totals.best,mission.best);
+  if (success){
+    career.totals.ops++;
+    career.op=Math.max(career.op,mission.op+1);
+  }
+  saveCareer();
+  lastDebrief={success,total,killCredits,completion,accBonus,speedBonus,subBonus,acc};
+  populateDebrief();
+  $('screen-debrief').classList.add('active');
+  sfx(success?'complete':'fail');
+}
+let lastDebrief=null;
+function populateDebrief(){
+  if (!mission || !lastDebrief) return;
+  const d=lastDebrief, cfg=mission.cfg;
+  $('debriefKicker').textContent=d.success?'OPERATION COMPLETE':'OPERATION FAILED';
+  $('debriefKicker').classList.toggle('fail',!d.success);
+  $('debriefTitle').textContent=cfg.name;
+  $('debriefSub').textContent=`SECTOR IRON VALLEY · ${WEATHER[cfg.weather].label} · OP ${String(mission.op).padStart(2,'0')}`;
+  $('dbKills').innerHTML=`${mission.kills}<small>/${mission.targets.length}</small>`;
+  $('dbAcc').innerHTML=`${Math.round(d.acc*100)}<small>%</small>`;
+  $('dbLong').innerHTML=`${Math.round(mission.best)}<small>m</small>`;
+  $('dbHeads').textContent=String(mission.headshots);
+  const rows=[
+    ['ELIMINATIONS', d.killCredits],
+    ['COMPLETION BONUS', d.completion],
+    ['ACCURACY BONUS', d.accBonus],
+    ['TIME BONUS', d.speedBonus]
+  ];
+  if (d.subBonus) rows.push(['SUBSONIC BONUS', d.subBonus]);
+  $('rewardList').innerHTML=rows.filter(r=>r[1]>0).map(r=>`<div class="reward-line"><span>${r[0]}</span><span>+${fmtInt(r[1])} CR</span></div>`).join('')
+    +`<div class="reward-line total"><span>TOTAL CREDITS</span><span>+${fmtInt(d.total)} CR</span></div>`;
+  const nextOp=career.op;
+  const nextCfg=opConfig(nextOp);
+  const nextLabel=d.success?`NEXT · OP ${String(nextOp).padStart(2,'0')} ${nextCfg.name}`:'REDEPLOY OPERATION';
+  $('debriefActions').innerHTML=`
+    <button class="btn primary" id="btnDebriefNext">${nextLabel}</button>
+    <button class="btn" id="btnDebriefArmory">ARMORY</button>
+    <button class="btn ghost" id="btnDebriefTitle">TITLE</button>`;
+  $('btnDebriefNext').onclick=()=>{ if(d.success){ showBriefing(); } else { deployMission(mission.op); } };
+  $('btnDebriefArmory').onclick=()=>{ armoryReturn='debrief'; showArmory(); };
+  $('btnDebriefTitle').onclick=()=>showTitle();
+}
+
+/* ============================================================
+   SCREENS
+   ============================================================ */
+function hideScreens(){ document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active')); }
+function showTitle(){
+  state='title'; mission=null; scope=null; bullets=[]; effects=[]; clearHudFeed();
+  currentWeather=opConfig(career.op).weather;
+  $('hud').classList.remove('on');
+  hideScreens(); $('screen-title').classList.add('active');
+  if (document.pointerLockElement) document.exitPointerLock();
+  const cfg=opConfig(career.op);
+  $('titleDeployOp').textContent='OP '+String(career.op).padStart(2,'0');
+  $('titleOp').textContent=String(career.op).padStart(2,'0')+(career.op>10?' VET':' / 10');
+  $('titleCredits').textContent=fmtInt(career.credits);
+  $('titleRifle').textContent=RIFLE_BY_ID[career.rifle].name;
+  $('titleBest').textContent=career.totals.best?Math.round(career.totals.best)+' m':'—';
+  const badge=$('padBadgeTitle');
+  badge.classList.toggle('on',gamepadState.index>=0);
+  $('padTextTitle').textContent=gamepadState.index>=0?'GAMEPAD CONNECTED':'GAMEPAD OPTIONAL';
+  $('btnDeploy').onclick=()=>showBriefing();
+  $('btnArmoryTitle').onclick=()=>{ armoryReturn='title'; showArmory(); };
+  armorySel=career.rifle;
+  updateAttractWeather();
+}
+let armoryReturn='title';
+let armorySel='m24';
+function updateAttractWeather(){
+  if (state==='title'||state==='briefing'||state==='armory'||state==='debrief'){
+    if (state==='title') currentWeather=opConfig(career.op).weather;
+  }
+}
+function showBriefing(){
+  state='briefing'; mission=null; scope=null;
+  currentWeather=opConfig(career.op).weather;
+  const cfg=opConfig(career.op);
+  const lo=getLoadout();
+  hideScreens(); $('screen-briefing').classList.add('active');
+  $('hud').classList.remove('on');
+  $('briefNum').textContent=String(career.op).padStart(2,'0');
+  $('briefName').textContent=cfg.name;
+  $('briefWeatherHead').textContent=WEATHER[cfg.weather].label+' / '+(cfg.weather==='dusk'?'DUSK':'DAY');
+  $('briefTimeHead').textContent=fmtTime(cfg.time)+' WINDOW';
+  $('briefContacts').textContent=String(cfg.targets);
+  $('briefRange').textContent=formatRangeBand(cfg);
+  $('briefWind').textContent=`${cfg.wmin}–${cfg.wmax} m/s`;
+  $('briefWeather').textContent=WEATHER[cfg.weather].label;
+  $('briefTime').textContent=fmtTime(cfg.time);
+  $('briefThreat').textContent=cfg.threat;
+  $('briefNote').textContent=cfg.note;
+  $('briefRifle').textContent=lo.rifle.name;
+  $('briefAmmo').textContent=lo.ammo.name;
+  $('briefOptic').textContent=lo.zoom.toFixed(1)+'×';
+  $('briefZero').textContent='200 M';
+  const diff=clamp(career.op,1,10);
+  $('briefDiff').innerHTML=Array.from({length:10},(_,i)=>`<i class="${i<diff?'on':''}"></i>`).join('');
+  drawBriefMap(career.op,cfg);
+  $('btnBriefBack').onclick=showTitle;
+  $('btnBriefArmory').onclick=()=>{ armoryReturn='briefing'; showArmory(); };
+  $('btnBriefDeploy').onclick=()=>deployMission(career.op);
+  updateAttractWeather();
+}
+function drawBriefMap(opNum,cfg){
+  const c=$('briefMap'), g=c.getContext('2d');
+  const w=c.width, h=c.height;
+  const rnd=mulberry32(0x51a7 ^ (opNum*7717));
+  g.clearRect(0,0,w,h);
+  g.fillStyle='#0a130c'; g.fillRect(0,0,w,h);
+  // grid
+  g.strokeStyle='rgba(145,170,130,.10)'; g.lineWidth=1;
+  for (let x=0;x<w;x+=26){ g.beginPath(); g.moveTo(x,0); g.lineTo(x,h); g.stroke(); }
+  for (let y=0;y<h;y+=26){ g.beginPath(); g.moveTo(0,y); g.lineTo(w,y); g.stroke(); }
+  // river
+  g.strokeStyle='rgba(103,151,150,.5)'; g.lineWidth=7;
+  g.beginPath(); g.moveTo(120,0);
+  for (let y=0;y<=h;y+=20) g.lineTo(120+40*Math.sin(y*0.023+1)+8*Math.sin(y*0.07),y);
+  g.stroke();
+  g.strokeStyle='rgba(170,200,190,.25)'; g.lineWidth=1.5; g.stroke();
+  // road
+  g.strokeStyle='rgba(180,160,110,.38)'; g.lineWidth=2;
+  g.beginPath(); g.moveTo(30,h); g.quadraticCurveTo(260,170,500,30); g.stroke();
+  // contours
+  for (let i=0;i<11;i++){
+    const cx=20+rnd()*w, cy=20+rnd()*h, rx=30+rnd()*90, ry=14+rnd()*45, rot=rnd()*Math.PI;
+    g.strokeStyle=`rgba(133,157,109,${0.10+rnd()*0.10})`; g.lineWidth=1;
+    g.beginPath(); g.ellipse(cx,cy,rx,ry,rot,0,TAU); g.stroke();
+    if (rnd()>0.35){ g.beginPath(); g.ellipse(cx,cy,rx*0.65,ry*0.62,rot,0,TAU); g.stroke(); }
+  }
+  // target sectors (approximate)
+  const n=Math.min(cfg.targets,8);
+  for (let i=0;i<n;i++){
+    const tx=250+ (i-(n-1)/2)*34 + (rnd()-0.5)*26;
+    const ty=80 + rnd()*130;
+    g.strokeStyle='rgba(220,104,80,.7)'; g.lineWidth=1;
+    g.beginPath(); g.moveTo(tx,ty-5); g.lineTo(tx+5,ty+4); g.lineTo(tx-5,ty+4); g.closePath(); g.stroke();
+    if (i===0){ g.strokeStyle='rgba(220,104,80,.35)'; g.beginPath(); g.arc(tx,ty,12,0,TAU); g.stroke(); }
+  }
+  // observer position
+  g.fillStyle='#e5b45b'; g.beginPath(); g.arc(56,238,4,0,TAU); g.fill();
+  g.strokeStyle='rgba(229,180,91,.5)'; g.beginPath(); g.arc(56,238,10,0,TAU); g.stroke();
+  g.fillStyle='rgba(211,225,194,.6)'; g.font='8px ui-monospace,monospace';
+  g.fillText('OBSERVER',70,241);
+  g.fillText('SECTOR 7',24,26);
+  g.fillStyle='rgba(220,104,80,.85)'; g.fillText('HOSTILE',250,60);
+  g.fillStyle='rgba(140,170,130,.4)'; g.font='7px ui-monospace,monospace';
+  g.fillText('APPROACH',360,250);
+}
+
+/* ============================================================
+   ARMORY
+   ============================================================ */
+function showArmory(){
+  state='armory'; hideScreens(); $('screen-armory').classList.add('active'); $('hud').classList.remove('on');
+  armorySel=career.rifle;
+  renderArmory();
+  $('btnArmoryClose').onclick=()=>{
+    if (armoryReturn==='briefing') showBriefing();
+    else if (armoryReturn==='debrief' && lastDebrief){ state='debrief'; hideScreens(); $('screen-debrief').classList.add('active'); populateDebrief(); }
+    else showTitle();
+  };
+}
+function statBar(label, value, max, display){
+  const p=clamp(value/max,0,1)*100;
+  return `<div class="statline"><span>${label}</span><div class="statbar"><i style="width:${p}%"></i></div><b>${display}</b></div>`;
+}
+function renderArmory(){
+  $('armCredits').textContent=fmtInt(career.credits);
+  $('armRifleCount').textContent=`${career.ownedRifles.length} / ${RIFLES.length}`;
+  $('rifleList').innerHTML=RIFLES.map(r=>{
+    const owned=career.ownedRifles.includes(r.id);
+    const sel=r.id===armorySel;
+    const eq=r.id===career.rifle;
+    return `<div class="rifle-item ${sel?'sel':''} ${owned?'':'locked'} ${eq?'selected-rifle':''}" data-rifle="${r.id}">
+      <div class="rname"><span>${r.name}</span>${!owned?`<em>T${r.tier}</em>`:''}</div>
+      <div class="rsub">${r.cal} · ${r.mag} RD · ${(r.mv).toFixed(0)} M/S</div>
+      ${!owned?`<div class="rprice">${fmtInt(r.cost)} CR</div>`:''}
+    </div>`;
+  }).join('');
+  const r=RIFLE_BY_ID[armorySel];
+  const owned=career.ownedRifles.includes(r.id);
+  const up=career.upgrades[r.id]||{barrel:0,optic:0,stock:0,trigger:0};
+  const mv=r.mv*(1+0.04*(up.barrel||0));
+  const zoom=60/r.fov*Math.pow(1.08,up.optic||0);
+  const upgrades=UPGRADES.map(u=>{
+    const lvl=up[u.id]||0;
+    const maxed=lvl>=u.max;
+    const cost=maxed?0:u.costs[lvl];
+    const can=owned&&!maxed&&career.credits>=cost;
+    return `<div class="upgrade-row">
+      <div class="un">${u.name}<small>${u.desc}</small></div>
+      <div class="pips">${Array.from({length:u.max},(_,i)=>`<i class="${i<lvl?'on':''}"></i>`).join('')}</div>
+      <button class="upbuy" data-upgrade="${u.id}" ${can?'':'disabled'}>${maxed?'MAX':fmtInt(cost)}</button>
+    </div>`;
+  }).join('');
+  $('rifleDetail').innerHTML=`
+    <div class="dname">${r.name}</div>
+    <div class="dcal">${r.cal} · TIER ${r.tier}</div>
+    <div class="ddesc">${r.desc}</div>
+    ${statBar('VELOCITY',mv,1000,Math.round(mv)+' m/s')}
+    ${statBar('BALLISTIC',r.bc,0.82,r.bc.toFixed(2)+' BC')}
+    ${statBar('MAGNIFICATION',zoom,13,zoom.toFixed(1)+'×')}
+    ${statBar('STABILITY',1/r.sway,1.9,(1/r.sway).toFixed(2))}
+    ${statBar('RECOIL',3-r.recoil,2.6,(3-r.recoil).toFixed(2))}
+    ${statBar('CAPACITY',r.mag,12,r.mag+' rd')}
+    ${statBar('RELOAD',4.6-r.reload,2.4,(4.6-r.reload).toFixed(2))}
+    ${!owned?`<div style="margin-top:14px"><button class="btn primary" id="btnBuyRifle" ${career.credits>=r.cost?'':'disabled'}>ACQUIRE · ${fmtInt(r.cost)} CR</button></div>`:''}
+    <div class="upgrade-row" style="border-top:1px solid var(--line2);margin-top:12px;padding-top:10px"><div class="un" style="color:var(--amber2)">PLATFORM UPGRADES<small>PER-RIFLE · CREDITS SPENT ARE PERMANENT</small></div></div>
+    ${upgrades}
+    <div class="comp-card">
+      <div class="ct">BALLISTIC COMPUTER<small>Unlocks T · computes elevation and windage to the ranged contact.</small></div>
+      <button class="upbuy" id="btnBuyComputer" ${career.computer?'disabled':''}>${career.computer?'INSTALLED':fmtInt(2400)+' CR'}</button>
+    </div>`;
+  $('ammoList').innerHTML=AMMO.map(a=>{
+    const own=career.ownedAmmo.includes(a.id);
+    const sel=career.ammo===a.id;
+    return `<div class="ammo-item ${sel?'sel':''} ${own?'':'locked'}" data-ammo="${a.id}">
+      <div class="an"><span>${a.name}</span>${sel?'<em>LOADED</em>':own?'<em>OWNED</em>':''}</div>
+      <div class="as">${a.desc}</div>
+      ${!own?`<span class="ap">${fmtInt(a.cost)} CR</span>`:''}
+    </div>`;
+  }).join('');
+  // listeners
+  document.querySelectorAll('[data-rifle]').forEach(el=>el.onclick=()=>{ armorySel=el.dataset.rifle; sfx('click'); renderArmory(); });
+  document.querySelectorAll('[data-ammo]').forEach(el=>el.onclick=()=>{
+    const id=el.dataset.ammo;
+    if (career.ownedAmmo.includes(id)){ career.ammo=id; saveCareer(); sfx('click'); renderArmory(); }
+    else { buyAmmo(id); }
+  });
+  document.querySelectorAll('[data-upgrade]').forEach(el=>el.onclick=()=>buyUpgrade(armorySel,el.dataset.upgrade));
+  const br=$('btnBuyRifle'); if (br) br.onclick=buySelectedRifle;
+  const bc=$('btnBuyComputer');
+  if (bc) bc.onclick=()=>{
+    if (career.computer||career.credits<2400) return;
+    career.credits-=2400; career.computer=true; saveCareer(); sfx('buy'); renderArmory();
+  };
+}
+function buySelectedRifle(){
+  const r=RIFLE_BY_ID[armorySel];
+  if (!r||career.ownedRifles.includes(r.id)||career.credits<r.cost) return;
+  career.credits-=r.cost; career.ownedRifles.push(r.id); career.rifle=r.id;
+  if (!career.upgrades[r.id]) career.upgrades[r.id]={barrel:0,optic:0,stock:0,trigger:0};
+  saveCareer(); sfx('buy'); renderArmory();
+}
+function buyAmmo(id){
+  const a=AMMO_BY_ID[id];
+  if (!a||career.ownedAmmo.includes(id)||career.credits<a.cost) return;
+  career.credits-=a.cost; career.ownedAmmo.push(id); career.ammo=id;
+  saveCareer(); sfx('buy'); renderArmory();
+}
+function buyUpgrade(rifleId,upId){
+  const r=RIFLE_BY_ID[rifleId];
+  if (!r||!career.ownedRifles.includes(rifleId)) return;
+  const u=UPGRADES.find(x=>x.id===upId);
+  if (!u) return;
+  const up=career.upgrades[rifleId]||{barrel:0,optic:0,stock:0,trigger:0};
+  const lvl=up[upId]||0;
+  if (lvl>=u.max) return;
+  const cost=u.costs[lvl];
+  if (career.credits<cost) return;
+  career.credits-=cost; up[upId]=lvl+1; career.upgrades[rifleId]=up;
+  saveCareer(); sfx('buy'); renderArmory();
+}
+
+/* ============================================================
+   PAUSE
+   ============================================================ */
+function pauseGame(){
+  if (state!=='mission') return;
+  state='paused';
+  hideScreens(); $('screen-pause').classList.add('active');
+  $('pauseSub').textContent=`OPERATION ${String(mission.op).padStart(2,'0')} · ${mission.cfg.name}`;
+  if (document.pointerLockElement) document.exitPointerLock();
+  $('btnResume').onclick=resumeGame;
+  $('btnRestart').onclick=()=>{ hideScreens(); deployMission(mission.op); };
+  $('btnAbandon').onclick=()=>{ hideScreens(); showTitle(); };
+  $('btnMute').textContent='SOUND: '+(muted?'OFF':'ON');
+  $('btnMute').onclick=()=>{ muted=!muted; career.settings.mute=muted; saveCareer(); updateMute(); $('btnMute').textContent='SOUND: '+(muted?'OFF':'ON'); };
+}
+function resumeGame(){
+  if (state!=='paused') return;
+  state='mission'; hideScreens(); tryLock();
+}
 </script>
 </body>
 </html>

