input.newString:
function resumeGame(){
  if (state!=='paused') return;
  state='mission'; hideScreens(); tryLock();
}

/* ============================================================
   AUDIO
   ============================================================ */
let AC=null, master=null, ambientGain=null, noiseBuf=null;
function initAudio(){
  if (AC) return;
  try {
    AC=new (window.AudioContext||window.webkitAudioContext)();
    master=AC.createGain(); master.gain.value=career.settings.mute?0:0.34; master.connect(AC.destination);
    noiseBuf=AC.createBuffer(1,AC.sampleRate*1.5,AC.sampleRate);
    const d=noiseBuf.getChannelData(0);
    for (let i=0;i<d.length;i++) d[i]=Math.random()*2-1;
    ambientGain=AC.createGain(); ambientGain.gain.value=0.025; ambientGain.connect(master);
    const src=AC.createBufferSource(); src.buffer=noiseBuf; src.loop=true;
    const lp=AC.createBiquadFilter(); lp.type='lowpass'; lp.frequency.value=380; lp.Q.value=0.5;
    src.connect(lp); lp.connect(ambientGain); src.start();
  } catch(e){}
}
function updateMute(){ if (master) master.gain.value=muted?0:0.34; }
function startAmbient(){ initAudio(); if (AC && AC.state==='suspended') AC.resume(); }
function tone(freq,dur,type,vol,slide){
  if (!AC||muted) return;
  const o=AC.createOscillator(), g=AC.createGain();
  o.type=type||'sine'; o.frequency.value=freq;
  if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(20,slide),AC.currentTime+dur);
  g.gain.setValueAtTime(vol||0.08,AC.currentTime);
  g.gain.exponentialRampToValueAtTime(0.0001,AC.currentTime+dur);
  o.connect(g); g.connect(master); o.start(); o.stop(AC.currentTime+dur+0.02);
}
function noiseBurst(dur,filterFreq,vol,type){
  if (!AC||muted||!noiseBuf) return;
  const s=AC.createBufferSource(); s.buffer=noiseBuf;
  const f=AC.createBiquadFilter(); f.type=type||'lowpass'; f.frequency.value=filterFreq||900;
  const g=AC.createGain();
  g.gain.setValueAtTime(vol||0.25,AC.currentTime);
  g.gain.exponentialRampToValueAtTime(0.0001,AC.currentTime+dur);
  s.connect(f); f.connect(g); g.connect(master); s.start(); s.stop(AC.currentTime+dur+0.03);
}
function sfx(type,tier){
  if (!AC||muted) return;
  switch(type){
    case 'shot':
      noiseBurst(0.16, 620-tier*70, 0.44, 'lowpass');
      noiseBurst(0.05, 3000, 0.12, 'highpass');
      tone(72-tier*3,0.22,'sine',0.28,38);
      setTimeout(()=>{ if (AC&&!muted) noiseBurst(0.07,1400,0.10,'bandpass'); },180);
      break;
    case 'hit': tone(820,0.10,'square',0.06,540); noiseBurst(0.06,1400,0.10,'bandpass'); break;
    case 'head': tone(1200,0.16,'triangle',0.09,700); tone(1700,0.12,'sine',0.05,900); break;
    case 'impact': noiseBurst(0.12,500,0.08,'lowpass'); break;
    case 'range': tone(1450,0.06,'square',0.035); setTimeout(()=>tone(1900,0.06,'square',0.03),70); break;
    case 'solve': tone(620,0.08,'sine',0.05); setTimeout(()=>tone(880,0.10,'sine',0.05),80); setTimeout(()=>tone(1180,0.12,'sine',0.045),170); break;
    case 'click': tone(1100,0.025,'square',0.025); break;
    case 'bolt': noiseBurst(0.05,2200,0.12,'bandpass'); setTimeout(()=>noiseBurst(0.06,1200,0.10,'bandpass'),110); break;
    case 'reload': tone(420,0.06,'square',0.04); setTimeout(()=>tone(720,0.07,'square',0.04),150); break;
    case 'empty': tone(160,0.05,'square',0.03); break;
    case 'buy': tone(680,0.08,'triangle',0.05); setTimeout(()=>tone(1020,0.12,'triangle',0.05),80); break;
    case 'complete': tone(440,0.18,'triangle',0.06); setTimeout(()=>tone(660,0.18,'triangle',0.055),140); setTimeout(()=>tone(880,0.3,'triangle',0.05),280); break;
    case 'fail': tone(220,0.3,'sine',0.06,110); break;
    case 'thunder': noiseBurst(0.8,180,0.18,'lowpass'); break;
  }
}

/* ============================================================
   INPUT
   ============================================================ */
function toggleMute(){
  muted=!muted; career.settings.mute=muted; saveCareer(); updateMute();
  if (state==='paused') $('btnMute').textContent='SOUND: '+(muted?'OFF':'ON');
  else addFeed(muted?'AUDIO MUTED':'AUDIO ON','');
}
function keyDown(e){
  const k=e.key;
  const lk=k.toLowerCase();
  if (['arrowup','arrowdown','arrowleft','arrowright',' '].includes(lk) || k==='Tab') e.preventDefault();
  keys[lk]=true;
  if (e.repeat) return;
  if (lk==='m'){ toggleMute(); return; }
  if (state==='mission'){
    if (lk===' '){ fireShot(); return; }
    if (lk==='z'){ if (scope) scope.scoped=!scope.scoped; sfx('click'); return; }
    if (lk==='r'){ requestReload(); return; }
    if (lk==='f'){ rangeFind(); return; }
    if (lk==='t'){ applySolution(); return; }
    if (lk==='['||lk===','){ changeZero(-1); return; }
    if (lk===']'||lk==='.'){ changeZero(1); return; }
    if (lk>='1'&&lk<='5'){
      const idx=Number(lk)-1;
      const a=AMMO[idx];
      if (a && career.ownedAmmo.includes(a.id)){ career.ammo=a.id; saveCareer(); const lo=getLoadout(); scope.zeroAngle=solveZeroAngle(lo.mv,lo.bc,scope.zeroRange); clearSolution(); sfx('click'); addFeed('AMMO · '+a.name,''); updateHUD(true); }
      return;
    }
    if (lk==='p'||lk==='escape'){ pauseGame(); return; }
    if (lk==='h'){ showHelp=!showHelp; addFeed(showHelp?'HELP ON':'HELP OFF',''); }
  } else if (state==='paused'){
    if (lk==='p'||lk==='escape'||lk==='enter') resumeGame();
  } else if (state==='title'||state==='briefing'){
    if (lk==='enter'){ if (state==='title') showBriefing(); else deployMission(career.op); }
  }
}
function keyUp(e){ keys[e.key.toLowerCase()]=false; }
canvas.addEventListener('contextmenu',e=>e.preventDefault());
canvas.addEventListener('mousedown',e=>{
  e.preventDefault();
  if (state!=='mission') return;
  if (e.button===2){ mouse.right=true; return; }
  if (e.button===0){
    if (!pointerLocked){ tryLock(); }
    else fireShot();
  }
});
window.addEventListener('mouseup',e=>{
  if (e.button===2) mouse.right=false;
  if (e.button===0) mouse.left=false;
});
document.addEventListener('mousemove',e=>{
  if (state==='mission' && pointerLocked){
    mouse.dx+=e.movementX||0; mouse.dy+=e.movementY||0;
  }
});
document.addEventListener('pointerlockchange',()=>{
  pointerLocked=document.pointerLockElement===canvas;
  updateHUD(true);
});
document.addEventListener('pointerlockerror',()=>{ pointerLocked=false; });
window.addEventListener('keydown',keyDown);
window.addEventListener('keyup',keyUp);
window.addEventListener('blur',()=>{ for (const k in keys) keys[k]=false; if (state==='mission') pauseGame(); });

/* ---------- gamepad ---------- */
function pollGamepad(dt){
  const pads=navigator.getGamepads?navigator.getGamepads():[];
  let gp=null;
  if (pads){ for (const p of pads){ if (p&&p.connected){ gp=p; break; } } }
  if (!gp){
    if (gamepadState.index>=0){ gamepadState.index=-1; gamepadState.name=''; if (state==='title') showTitle(); }
    return;
  }
  if (gamepadState.index!==gp.index){
    gamepadState.index=gp.index; gamepadState.name=gp.id||'GAMEPAD';
    if (state==='title') showTitle();
  }
  const ax=gp.axes||[];
  gamepadState.axes=[ax[0]||0,ax[1]||0,ax[2]||0,ax[3]||0];
  const btn=i=>gp.buttons[i] ? (gp.buttons[i].pressed||gp.buttons[i].value>0.4) : false;
  const val=i=>gp.buttons[i] ? gp.buttons[i].value||0 : 0;
  const prev=gamepadState.prev;
  const edge=(i,name)=>btn(i)&&!prev[name];
  gamepadState.breath=btn(4)?1:0;
  gamepadState.scope=btn(6)?1:0;
  if (state==='mission' && scope){
    if (edge(7,'rt')) fireShot();
    if (edge(5,'rb')) rangeFind();
    if (edge(0,'a')) requestReload();
    if (edge(1,'b')) cycleAmmo();
    if (edge(3,'y')) applySolution();
    if (edge(2,'x')){ scope.scoped=!scope.scoped; sfx('click'); }
    if (edge(12,'du')) changeZero(1);
    if (edge(13,'dd')) changeZero(-1);
    if (edge(9,'start')) pauseGame();
  } else if (state==='paused' && edge(9,'start')){
    resumeGame();
  }
  if (state==='title'){
    const badge=$('padBadgeTitle');
    if (badge){ badge.classList.add('on'); $('padTextTitle').textContent='GAMEPAD CONNECTED'; }
  }
  gamepadState.prev={rt:btn(7),rb:btn(5),a:btn(0),b:btn(1),x:btn(2),y:btn(3),du:btn(12),dd:btn(13),start:btn(9)};
}
window.addEventListener('gamepadconnected',()=>{ if (state==='title') showTitle(); });
window.addEventListener('gamepaddisconnected',()=>{ gamepadState.index=-1; gamepadState.name=''; if (state==='title') showTitle(); });

/* ============================================================
   RENDER LOOP
   ============================================================ */
function renderScene(){
  if (!world) return;
  drawSky();
  drawGround();
  drawFields();
  drawRiver();
  drawRoad();
  drawSceneObjects();
  drawBullets();
  drawWorldEffects();
  drawMuzzleSmoke();
  drawWeatherOverlay();
  drawScopeOverlay();
  drawWeapon();
  drawHipCrosshair();
  if (mission && mission.fade>0.001 && state==='mission'){
    ctx.fillStyle=`rgba(0,0,0,${mission.fade*0.9})`;
    ctx.fillRect(0,0,W,H);
  }
  // vignette from fx layer handled by CSS; add lens dirt highlight
  if (scope && view.zoomT>0.5 && screenFlash>0.5){
    ctx.fillStyle='rgba(255,247,213,.04)'; ctx.fillRect(0,0,W,H);
  }
}
let lastFrame=performance.now();
function loop(now){
  requestAnimationFrame(loop);
  const dt=clamp((now-lastFrame)/1000,0,0.05);
  lastFrame=now;
  pollGamepad(dt);
  updateAmbient(dt);
  if (state==='mission'){
    updateMission(dt);
    updateHUD();
  } else if (state==='title'||state==='briefing'||state==='armory'){
    updateView(dt);
  } else if (state==='debrief' || state==='paused'){
    // frozen battlefield
  }
  renderScene();
}

/* ============================================================
   INIT / DEBUG
   ============================================================ */
generateWorld();
world.rain=Array.from({length:210},()=>({x:Math.random()*W,y:Math.random()*H,sp:420+Math.random()*520,l:10+Math.random()*20}));
muted=!!career.settings.mute;
showTitle();
requestAnimationFrame(loop);

window.GAME={
  get state(){return state;},
  get mission(){return mission;},
  get scope(){return scope;},
  get career(){return career;},
  get view(){return view;},
  deploy:(n)=>deployMission(n||career.op),
  aimAt:(i)=>{
    if (!mission||!mission.targets[i]) return false;
    const t=mission.targets[i];
    aim.yaw=Math.atan2(t.x,t.z);
    aim.pitch=Math.atan2(targetChestY(t),t.z);
    view.swayYaw=0; view.swayPitch=0; view.recoilPitch=0; view.recoilYaw=0;
    return true;
  },
  aimAtPoint:(x,y,z)=>{ aim.yaw=Math.atan2(x,z); aim.pitch=Math.atan2(y,z); },
  setScope:(on)=>{ if (scope) scope.scoped=!!on; view.zoomT=on?1:0; },
  fire:()=>fireShot(),
  range:()=>rangeFind(),
  solve:()=>applySolution(),
  reload:()=>requestReload(),
  setAmmo:(id)=>{ if (career.ownedAmmo.includes(id)){ career.ammo=id; saveCareer(); const lo=getLoadout(); if(scope){scope.zeroAngle=solveZeroAngle(lo.mv,lo.bc,scope.zeroRange); clearSolution();} return true;} return false; },
  zero:(m)=>{ if(scope){ scope.zeroRange=clamp(m,100,1000); const lo=getLoadout(); scope.zeroAngle=solveZeroAngle(lo.mv,lo.bc,scope.zeroRange); clearSolution(); } },
  giveCredits:(n)=>{ career.credits+=n; saveCareer(); if(state==='armory') renderArmory(); if(state==='title') showTitle(); },
  hideUI:()=>{ $('hud').classList.remove('on'); hideScreens(); },
  showScopeOnly:()=>{ if(scope) scope.scoped=true; view.zoomT=1; }
};
})();
</script>

