+/* ---------- gamepad ---------- */
+function pollGamepad(dt){
+  const pads=navigator.getGamepads?navigator.getGamepads():[];
+  let gp=null;
+  if (pads){ for (const p of pads){ if (p&&p.connected){ gp=p; break; } } }
+  if (!gp){
+    if (gamepadState.index>=0){ gamepadState.index=-1; gamepadState.name=''; if (state==='title') showTitle(); }
+    return;
+  }
+  if (gamepadState.index!==gp.index){
+    gamepadState.index=gp.index; gamepadState.name=gp.id||'GAMEPAD';
+    if (state==='title') showTitle();
+  }
+  const ax=gp.axes||[];
+  gamepadState.axes=[ax[0]||0,ax[1]||0,ax[2]||0,ax[3]||0];
+  const btn=i=>gp.buttons[i] ? (gp.buttons[i].pressed||gp.buttons[i].value>0.4) : false;
+  const val=i=>gp.buttons[i] ? gp.buttons[i].value||0 : 0;
+  const prev=gamepadState.prev;
+  const edge=(i,name)=>btn(i)&&!prev[name];
+  gamepadState.breath=btn(4)?1:0;
+  gamepadState.scope=btn(6)?1:0;
+  if (state==='mission' && scope){
+    if (edge(7,'rt')) fireShot();
+    if (edge(5,'rb')) rangeFind();
+    if (edge(0,'a')) requestReload();
+    if (edge(1,'b')) cycleAmmo();
+    if (edge(3,'y')) applySolution();
+    if (edge(2,'x')){ scope.scoped=!scope.scoped; sfx('click'); }
+    if (edge(12,'du')) changeZero(1);
+    if (edge(13,'dd')) changeZero(-1);
+    if (edge(9,'start')) pauseGame();
+  } else if (state==='paused' && edge(9,'start')){
+    resumeGame();
+  }
+  if (state==='title'){
+    const badge=$('padBadgeTitle');
+    if (badge){ badge.classList.add('on'); $('padTextTitle').textContent='GAMEPAD CONNECTED'; }
+  }
+  gamepadState.prev={rt:btn(7),rb:btn(5),a:btn(0),b:btn(1),x:btn(2),y:btn(3),du:btn(12),dd:btn(13),start:btn(9)};
+}
+window.addEventListener('gamepadconnected',()=>{ if (state==='title') showTitle(); });
+window.addEventListener('gamepaddisconnected',()=>{ gamepadState.index=-1; gamepadState.name=''; if (state==='title') showTitle(); });
