function fireShot(){
  if (state !== 'mission' || !mission || mission.ended) return;
  if (scope.cycle > 0 || scope.reload > 0) return;
  if (scope.ammo <= 0){ sfx('empty'); addFeed('MAGAZINE EMPTY · PRESS R','bad'); return; }
  const lo = getLoadout();
  scope.ammo--;
  scope.cycle = lo.rifle.cycle;
  scope.bolt = lo.rifle.cycle > 0.5 ? lo.rifle.cycle : 0;
  mission.shots++;
  mission.fired = true;
  for (const t of mission.targets){ if (t.alive) t.alert = true; }
  const fwd = {
    x:Math.sin(view.yaw)*Math.cos(view.pitch),
    y:Math.sin(view.pitch),
    z:Math.cos(view.yaw)*Math.cos(view.pitch)
  };
  const right = { x:Math.cos(view.yaw), y:0, z:-Math.sin(view.yaw) };
  const up = { x:fwd.y*right.z-fwd.z*right.y, y:fwd.z*right.x-fwd.x*right.z, z:fwd.x*right.y-fwd.y*right.x };
  const breathe = scope.holding && scope.breath>0 ? 0.55 : 1;
  const emptyBreath = scope.breath<=0 ? 1.7 : 1;
  const spreadBase = (view.zoomT>0.5 ? 0.00009 : 0.0062) * lo.spread * breathe * emptyBreath;
  const dispPitch = (Math.random()+Math.random()-1) * spreadBase;
  const dispYaw = (Math.random()+Math.random()-1) * spreadBase;
  const elev = scope.zeroAngle + scope.solution.elevMil/1000 + dispPitch;
  const lat = scope.solution.windMil/1000 + dispYaw;
  const ce=Math.cos(elev), se=Math.sin(elev);
  const cl=Math.cos(lat), sl=Math.sin(lat);
  let dx = fwd.x*ce + up.x*se + right.x*sl;
  let dy = fwd.y*ce + up.y*se + right.y*sl;
  let dz = fwd.z*ce + up.z*se + right.z*sl;
  const dl = Math.hypot(dx,dy,dz) || 1;
  dx/=dl; dy/=dl; dz/=dl;
  const start = { x:fwd.x*0.55, y:-0.08+fwd.y*0.55, z:fwd.z*0.55 };
  const b = {
    x:start.x, y:start.y, z:start.z,
    vx:dx*lo.mv, vy:dy*lo.mv, vz:dz*lo.mv,
    mv:lo.mv, bc:lo.bc, ammo:lo.ammo, tracer:lo.ammo.tracer,
    trail:[], t:0, alive:true, startDist:0,
    closest:1e9, closestTarget:null, closestOffsets:null
  };
  bullets.push(b);
  // recoil
  const kick = 0.0135 * lo.rifle.recoil * (view.zoomT>0.5 ? 1.15 : 1);
  view.rvP += kick*18;
  view.rvY += (Math.random()-0.5)*kick*9;
  view.shake = Math.max(view.shake, 0.0035*lo.rifle.recoil);
  screenFlash = Math.max(screenFlash, view.zoomT>0.5 ? 0.55 : 0.8);
  addMuzzleSmoke();
  sfx('shot', lo.rifle.tier);
  addFeed(`${lo.rifle.name} · ${lo.ammo.short} · ${Math.round(scope.range.dist||0)||'--'} M`, '');
  scope.solution.time = Math.max(0, scope.solution.time - 0.6);
}

