  const k=e.key;
  const lk=k.toLowerCase();
  if (['arrowup','arrowdown','arrowleft','arrowright',' '].includes(lk) || k==='Tab') e.preventDefault();
  keys[lk]=true;
  if (e.repeat) return;
  if (lk==='m'){ toggleMute(); return; }
  if (state==='mission'){
    if (lk===' '){ fireShot(); return; }
    if (lk==='z'){ if (scope) scope.scoped=!scope.scoped; sfx('click'); return; }
    if (lk==='r'){ requestReload(); return; }
    if (lk==='f'){ rangeFind(); return; }
    if (lk==='t'){ applySolution(); return; }
    if (lk==='['||lk===','){ changeZero(-1); return; }
    if (lk===']'||lk==='.'){ changeZero(1); return; }
    if (lk>='1'&&lk<='5'){
      const idx=Number(lk)-1;
      const a=AMMO[idx];
      if (a && career.ownedAmmo.includes(a.id)){ career.ammo=a.id; saveCareer(); const lo=getLoadout(); scope.zeroAngle=solveZeroAngle(lo.mv,lo.bc,scope.zeroRange); clearSolution(); sfx('click'); addFeed('AMMO · '+a.name,''); updateHUD(true); }
      return;
    }
    if (lk==='p'||lk==='escape'){ pauseGame(); return; }
    if (lk==='h'){ showHelp=!showHelp; addFeed(showHelp?'HELP ON':'HELP OFF',''); }
  } else if (state==='paused'){
    if (lk==='p'||lk==='escape'||lk==='enter') resumeGame();
  } else if (state==='title'||state==='briefing'){
    if (lk==='enter'){ if (state==='title') showBriefing(); else deployMission(career.op); }
  }
}
