function drawSky(){
  const w = weather();
  const g = ctx.createLinearGradient(0,0,0,H*0.92);
  g.addColorStop(0, w.skyTop);
  g.addColorStop(0.52, mixHex(w.skyTop, w.skyMid, 0.78));
  g.addColorStop(0.78, w.skyMid);
  g.addColorStop(1, w.skyLow);
  ctx.fillStyle = g; ctx.fillRect(0,0,W,H);

  // sun / moon glow
  const D = 7000;
  const sunP = project(Math.sin(w.sunAz)*D, Math.tan(w.sunEl)*D, Math.cos(w.sunAz)*D);
  if (sunP && sunP.z > 0){
    const r = clamp(260 / Math.max(0.4, view.fov/rad(60)), 90, 420);
    const gg = ctx.createRadialGradient(sunP.x,sunP.y,2,sunP.x,sunP.y,r);
    gg.addColorStop(0, alpha(w.sun, currentWeather === 'dusk' ? 0.95 : 0.7));
    gg.addColorStop(0.12, alpha(w.sun, 0.35));
    gg.addColorStop(0.45, alpha(w.sun, 0.1));
    gg.addColorStop(1, alpha(w.sun, 0));
    ctx.fillStyle = gg; ctx.beginPath(); ctx.arc(sunP.x,sunP.y,r,0,TAU); ctx.fill();
    if (sunP.x > -200 && sunP.x < W+200 && sunP.y > -200 && sunP.y < H+200){
      ctx.fillStyle = alpha('#ffffff', currentWeather==='dusk'?0.72:0.55);
      ctx.beginPath(); ctx.arc(sunP.x,sunP.y, currentWeather==='dusk'?8:5, 0, TAU); ctx.fill();
    }
  }

  // clouds
  for (const c of world.clouds){
    const az = c.az + ambientTime*c.drift*0.05;
    const el = c.el + Math.sin(ambientTime*0.02+c.az*9)*0.004;
    const p0 = project(Math.sin(az)*5200, Math.tan(el)*5200, Math.cos(az)*5200);
    if (!p0 || p0.z <= 0) continue;
    const f = focal();
    const wpx = (f/5200) * 5200 * Math.tan(c.w);
    const hpx = Math.max(7, wpx * 0.17);
    if (p0.x < -wpx || p0.x > W+wpx || p0.y < -hpx || p0.y > H+hpx) continue;
    ctx.save();
    ctx.globalAlpha = c.a * (0.45 + 0.55*Math.max(0, Math.cos((az-view.yaw)*0.9)));
