  }

  // mountain layers
  const layers = [
    {base:0.0, col:mixHex(w.skyLow,w.fog,0.38), snow:0.5, step:7},
    {base:0.0, col:mixHex(w.groundDark,w.fog,0.56), snow:0.0, step:6},
    {base:0.0, col:mixHex(w.groundDark,w.fog,0.34), snow:0.0, step:4}
  ];
  const f = focal();
  for (let li=0; li<3; li++){
    const L = layers[li];
    ctx.beginPath();
    let first = true;
    for (let x=-24; x<=W+24; x+=L.step){
      const az = view.yaw + screenAngleAt(x);
      let el = mountainElev(az, li);
      if (li === 2) el *= 0.62;
      const yy = H/2 - f*Math.tan(clamp(el - view.pitch, -1.2, 1.2));
      if (first){ ctx.moveTo(x, yy); first = false; }
