    ctx.fillStyle = L.col; ctx.fill();
    if (li === 0){
      ctx.strokeStyle = alpha(w.skyLow, 0.18); ctx.lineWidth = 1.5; ctx.stroke();
    }
  }

  // horizon haze
  const hy = horizonY();
  if (hy > -80 && hy < H+80){
    const gg = ctx.createLinearGradient(0,hy-46,0,hy+54);
    gg.addColorStop(0, alpha(w.fog,0));
    gg.addColorStop(0.55, alpha(w.fog,0.62));
    gg.addColorStop(1, alpha(w.fog,0));
    ctx.fillStyle = gg; ctx.fillRect(0,hy-46,W,100);
  }

  // birds
  for (const b of world.birds){
    const az = b.az + Math.sin(ambientTime*0.07+b.seed)*0.06 + b.speed*Math.sin(ambientTime*0.13);
    const p = project(Math.sin(az)*2600, Math.tan(b.el+0.01*Math.sin(ambientTime*0.4+b.seed))*2600, Math.cos(az)*2600);
    if (!p || p.z <= 0 || p.x < -30 || p.x > W+30 || p.y < -30 || p.y > H) continue;
    const sz = clamp(b.w*45, 2, 8);
    const flap = Math.sin(ambientTime*3.1+b.seed*7)*0.5+0.5;
    ctx.strokeStyle = alpha('#26302a', 0.55);
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.moveTo(p.x-sz, p.y+flap*sz*0.3); ctx.quadraticCurveTo(p.x-sz*0.4,p.y-sz*0.4,p.x,p.y);
    ctx.quadraticCurveTo(p.x+sz*0.4,p.y-sz*0.4,p.x+sz,p.y+flap*sz*0.3);
    ctx.stroke();
  }
}

function drawGround(){
