function drawMound(t){
  const base = project(t.x, GROUND_Y, t.z+1.5);
  const top = project(t.x, t.groundY, t.z);
  if (!base || !top) return;
  const s = base.s;
  const rx = 16*s, ry = Math.max(2, (top.y-base.y)*1.15);
  const col = fogged(weather().ground, t.z);
  const col2 = fogged(shade(weather().ground,0.9), t.z);
  ctx.fillStyle = col2;
  ctx.beginPath();
  ctx.ellipse(base.x, base.y, rx, ry, 0, Math.PI, TAU);
  ctx.lineTo(base.x+rx, base.y+2); ctx.lineTo(base.x-rx, base.y+2); ctx.closePath(); ctx.fill();
  ctx.fillStyle = alpha('#d6dfc2', 0.045);
  ctx.beginPath(); ctx.ellipse(base.x, top.y+ry*0.1, rx*0.46, ry*0.15, 0,0,TAU); ctx.fill();
}

function drawCoverWall(t, height){
  const base = project(t.x, t.groundY, t.z-0.65);
  if (!base) return;
  const s = base.s, w = 1.28*s, h = (height||1.0)*s;
  if (h < 1.2) return;
  const col = fogged('#8d7c58', t.z-0.65);
  const dark = fogged('#5f533b', t.z-0.65);
  if (h < 5){
    ctx.fillStyle = col; ctx.fillRect(base.x-w/2, base.y-h, w, h);
    ctx.fillStyle = dark; ctx.fillRect(base.x-w/2, base.y-h*0.25, w, h*0.25);
    return;
  }
  const rows = 3;
  for (let r=0;r<rows;r++){
    const yy = base.y - h*(0.16 + r*0.28);
    const off = (r%2)*w*0.11;
    for (let i=-1;i<=1;i++){
      ctx.fillStyle = r===1 ? fogged('#97865e',t.z) : col;
      ctx.beginPath(); ctx.ellipse(base.x + i*w*0.29 + off, yy, w*0.19, h*0.17, 0,0,TAU); ctx.fill();
      ctx.strokeStyle = alpha('#413922',0.35); ctx.lineWidth = 1; ctx.stroke();
    }
  }
}

