  ctx.fillStyle = fogged('#2a2b21', t.z);
  ctx.fillRect(-0.23+legSwing, -0.10, 0.22, 0.10);
  ctx.fillRect(0.01+legSwing2, -0.10, 0.22, 0.10);
  // torso
  ctx.fillStyle = uni;
  ctx.beginPath();
  ctx.moveTo(-0.25,-1.50+bob); ctx.lineTo(0.25,-1.50+bob);
  ctx.lineTo(0.28,-0.82); ctx.lineTo(-0.28,-0.82); ctx.closePath(); ctx.fill();
  // vest
  ctx.fillStyle = vest;
  ctx.fillRect(-0.21,-1.30+bob,0.42,0.36);
  ctx.fillStyle = fogged('#2d3325',t.z);
  ctx.fillRect(-0.17,-1.05+bob,0.34,0.08);
  // arms
  ctx.fillStyle = uni;
  ctx.fillRect(-0.32,-1.42+bob,0.10,0.55);
  ctx.fillRect(0.22,-1.42+bob,0.10,0.50);
  // rifle
  ctx.strokeStyle = alpha('#1c2119',0.9); ctx.lineWidth = 0.055;
  ctx.beginPath(); ctx.moveTo(-0.22,-1.12+bob); ctx.lineTo(0.34,-1.02+bob); ctx.stroke();
  // head
  ctx.fillStyle = skin;
  ctx.beginPath(); ctx.arc(0,-1.64+bob,0.135,0,TAU); ctx.fill();
  ctx.fillStyle = helmet;
  ctx.beginPath(); ctx.arc(0,-1.68+bob,0.155,Math.PI*1.02,TAU*0.99); ctx.fill();
  ctx.fillRect(-0.16,-1.68+bob,0.32,0.075);
  // face shadow
  ctx.fillStyle = alpha('#2a241d',0.7);
  ctx.fillRect(-0.05,-1.62+bob,0.13,0.035);
  // armband
  if (bodyH > 22){
    ctx.fillStyle = fogged('#9a3c2f', t.z);
    ctx.fillRect(-0.31,-1.34+bob,0.055,0.11);
  }
  // rim light
  if (fog < 0.8){
    ctx.strokeStyle = alpha('#e7e0bd', 0.12*(1-fog));
    ctx.lineWidth = 0.02;
    ctx.beginPath(); ctx.moveTo(-0.24,-1.5+bob); ctx.lineTo(-0.27,-0.82); ctx.stroke();
  }
  ctx.restore();
  if (t.cover) drawCoverWall(t, 1.0);
  // glint
  if (t.alive && (!t.popup || t.up)){
    const pulse = Math.sin(ambientTime*1.35 + t.seed*9);
    if (pulse > 0.74 || bodyH > 30){
      const hp = project(t.x, targetHeadY(t)+0.12, t.z);
      if (hp && fog < 0.9){
        const gA = 0.35 + 0.35*Math.max(0,pulse);
        const rr = bodyH > 45 ? 4 : 2.6;
        ctx.fillStyle = alpha('#fff0be', gA*(1-fog));
        ctx.beginPath(); ctx.arc(hp.x,hp.y,Math.max(1,rr*0.35),0,TAU); ctx.fill();
        ctx.strokeStyle = alpha('#fff0be', gA*0.8);
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(hp.x-rr,hp.y); ctx.lineTo(hp.x+rr,hp.y);
        ctx.moveTo(hp.x,hp.y-rr); ctx.lineTo(hp.x,hp.y+rr);
        ctx.stroke();
      }
    }
  }
  if (!t.alive && t.deadT < 1.2 && t.deadT > 0.02){
    // brief death marker
    const hp = project(t.x, t.groundY+1.1, t.z);
    if (hp){ ctx.fillStyle = alpha('#d05a42', 0.22*(1-t.deadT/1.2)); ctx.beginPath(); ctx.arc(hp.x,hp.y,bodyH*0.38,0,TAU); ctx.fill(); }
  }
}

/* ============================================================
   MISSION CREATION
   ============================================================ */
function clearSolution(){ if (scope){ scope.solution = {elevMil:0, windMil:0, active:false, time:0}; } }
function makeTarget(cfg, i, n, rnd, opNum){
  const z = cfg.rmin + (cfg.rmax-cfg.rmin)*((i+0.35+rnd()*0.3)/n);
  let az = -0.30 + 0.60*((i+0.5)/n) + (rnd()-0.5)*0.05;
  let x = Math.tan(az)*z;
  let tries = 0;
  while (tries++ < 12){
    let blocked = false;
    for (const p of world.props){
      if ((p.type==='building'||p.type==='pine'||p.type==='broad'||p.type==='tower'||p.type==='silo')){
        if (Math.hypot(p.x-x, p.z-z) < 26){ blocked = true; break; }
      }
    }
    if (!blocked) break;
    az += (rnd()-0.5)*0.08;
    x = Math.tan(az)*z;
  }
  let type = cfg.types[i % cfg.types.length];
  if (type === 'static' && rnd()<0.28) type = 'walk';
  const cover = type !== 'runner' && rnd() < cfg.cover;
  const popup = type === 'popup';
  const mound = rnd() < 0.18 ? 2.5 + rnd()*6 : 0;
  const groundY = GROUND_Y + mound;
  const span = type==='runner' ? 60 + rnd()*100 : type==='walk' ? 10 + rnd()*26 : 4 + rnd()*8;
  const speed = type==='runner' ? 3.0 + rnd()*3.0 : type==='walk' ? 0.7 + rnd()*1.4 : 0;
  const dir = rnd()<0.5 ? -1 : 1;
  const t = {
    id:i, x, baseX:x, z, groundY, mound, type, cover, popup,
    alive:true, up:true, popT: popup ? 2.0+rnd()*2.5 : 0, deadT:0, fallDir: dir,
    walkPhase: rnd()*TAU, speed, dir, span, seed:rnd()*99,
    uniform: rnd()<0.5?'#4b5238':'#54563a', vest: rnd()<0.5?'#333a2a':'#3e3d2b',
    alert:false, hitHead:false
  };
  if (type==='static' || popup) t.x = x + (rnd()-0.5)*span;
  return t;
}

function createMission(opNum){
  const cfg = opConfig(opNum);
  currentWeather = cfg.weather;
  const rnd = mulberry32(0x9e3779b9 ^ (opNum*7919));
  const targets = [];
  const n = cfg.targets;
  for (let i=0;i<n;i++) targets.push(makeTarget(cfg, i, n, rnd, opNum));
  const baseAngle = (rnd()*2-1)*0.55;
  const baseSpeed = cfg.wmin + rnd()*(cfg.wmax-cfg.wmin);
  const base = {
    op:opNum, cfg, targets, kills:0, shots:0, headshots:0, best:0, killLog:[],
    timeLimit:cfg.time, timeLeft:cfg.time, ended:false, completed:false, endDelay:-1,
    startTime:0, wind:{ baseSpeed, baseAngle, t:rnd()*10, speed:baseSpeed, angle:baseAngle, vx:0, vz:0 },
    fired:false, fade:1
  };
  // wind vector initial
  updateWindVector(base);
  return base;
}

}

function updateWindVector(m){
  const w=m.wind;
  w.speed = Math.max(0, w.baseSpeed*(1 + 0.20*Math.sin(w.t*0.43+1.2) + 0.09*Math.sin(w.t*1.87+0.4)));
  w.angle = w.baseAngle + 0.14*Math.sin(w.t*0.11+0.8);
  w.vx = Math.cos(w.angle)*w.speed;
  w.vz = Math.sin(w.angle)*w.speed;
}

/* ============================================================
   EXTERNAL BALLISTICS
   ============================================================ */
function simulateShot(o){
  const dt = o.dt || 0.0015;
  const maxT = o.maxT || 5.5;
  let x=0,y=0,z=0;
  let vx=Math.sin(o.lat||0)*o.mv;
  let vy=Math.sin(o.angle||0)*o.mv;
  let vz=Math.cos(o.lat||0)*Math.cos(o.angle||0)*o.mv;
  const k = 0.0006 / Math.max(0.08,o.bc);
  const wx = o.wind ? o.wind.vx||0 : 0;
  const wz = o.wind ? o.wind.vz||0 : 0;
  let t=0, closest=1e9, closestAt=null;
  while (t<maxT){
    const rx=vx-wx, ry=vy, rz=vz-wz;
    const sp=Math.hypot(rx,ry,rz);
    const ax=-k*sp*rx, ay=-9.81-k*sp*ry, az=-k*sp*rz;
    vx+=ax*dt; vy+=ay*dt; vz+=az*dt;
    x+=vx*dt; y+=vy*dt; z+=vz*dt;
    t+=dt;
    if (z >= o.range){ closest=Math.hypot(x,y); closestAt={x,y,z,t}; break; }
    if (y < -80) break;
  }
  return closestAt || {x,y,z,t};
}
function solveZeroAngle(mv, bc, range){
  let lo=-0.015, hi=0.16;
  for (let i=0;i<26;i++){
    const mid=(lo+hi)/2;
    const r=simulateShot({mv,bc,angle:mid,range:Math.max(20,range),dt:0.002});
    if (r.y < 0) lo=mid; else hi=mid;
  }
  return (lo+hi)/2;
}
function windInAimFrame(w, yaw){
  const c=Math.cos(yaw), s=Math.sin(yaw);
  return { vx:w.vx*c - w.vz*s, vz:w.vx*s + w.vz*c };
}
function predictHold(range, wind){
  if (!mission || !scope) return {hold:0, drift:0};
  const lo = getLoadout();
  const elev = scope.zeroAngle + scope.solution.elevMil/1000;
  const lat = scope.solution.windMil/1000;
  const r = simulateShot({mv:lo.mv, bc:lo.bc, angle:elev, lat, range, wind:windInAimFrame(wind,view.yaw), dt:0.002});
  return { hold: -r.y/range*1000, drift: -r.x/range*1000 };
}

/* ============================================================
   FIRE / HIT
   ============================================================ */
function fireShot(){
  if (state !== 'mission' || !mission || mission.ended) return;
  if (scope.cycle > 0 || scope.reload > 0) return;
  if (scope.ammo <= 0){ sfx('empty'); addFeed('MAGAZINE EMPTY · PRESS R','bad'); return; }
  const lo = getLoadout();
  scope.ammo--;
  scope.cycle = lo.rifle.cycle;
  scope.bolt = lo.rifle.cycle > 0.5 ? lo.rifle.cycle : 0;
  mission.shots++;
  mission.fired = true;
  for (const t of mission.targets){ if (t.alive) t.alert = true; }
  const fwd = {
    x:Math.sin(view.yaw)*Math.cos(view.pitch),
    y:Math.sin(view.pitch),
    z:Math.cos(view.yaw)*Math.cos(view.pitch)
  };
  const right = { x:Math.cos(view.yaw), y:0, z:-Math.sin(view.yaw) };
  const up = { x:fwd.y*right.z-fwd.z*right.y, y:fwd.z*right.x-fwd.x*right.z, z:fwd.x*right.y-fwd.y*right.x };
  const breathe = scope.holding && scope.breath>0 ? 0.55 : 1;
  const emptyBreath = scope.breath<=0 ? 1.7 : 1;
  const spreadBase = (view.zoomT>0.5 ? 0.00009 : 0.0062) * lo.spread * breathe * emptyBreath;
  const dispPitch = (Math.random()+Math.random()-1) * spreadBase;
  const dispYaw = (Math.random()+Math.random()-1) * spreadBase;
  const elev = scope.zeroAngle + scope.solution.elevMil/1000 + dispPitch;
  const lat = scope.solution.windMil/1000 + dispYaw;
  const ce=Math.cos(elev), se=Math.sin(elev);
  const cl=Math.cos(lat), sl=Math.sin(lat);
  let dx = fwd.x*ce + up.x*se + right.x*sl;
  let dy = fwd.y*ce + up.y*se + right.y*sl;
  let dz = fwd.z*ce + up.z*se + right.z*sl;
  const dl = Math.hypot(dx,dy,dz) || 1;
  dx/=dl; dy/=dl; dz/=dl;
  const start = { x:fwd.x*0.55, y:-0.08+fwd.y*0.55, z:fwd.z*0.55 };
  const b = {
    x:start.x, y:start.y, z:start.z,
    vx:dx*lo.mv, vy:dy*lo.mv, vz:dz*lo.mv,
    mv:lo.mv, bc:lo.bc, ammo:lo.ammo, tracer:lo.ammo.tracer,
    trail:[], t:0, alive:true, startDist:0,
    closest:1e9, closestTarget:null, closestOffsets:null
  };
  bullets.push(b);
  // recoil
  const kick = 0.0135 * lo.rifle.recoil * (view.zoomT>0.5 ? 1.15 : 1);
  view.rvP += kick*18;
  view.rvY += (Math.random()-0.5)*kick*9;
  view.shake = Math.max(view.shake, 0.0035*lo.rifle.recoil);
  screenFlash = Math.max(screenFlash, view.zoomT>0.5 ? 0.55 : 0.8);
  addMuzzleSmoke();
  sfx('shot', lo.rifle.tier);
  addFeed(`${lo.rifle.name} · ${lo.ammo.short} · ${Math.round(scope.range.dist||0)||'--'} M`, '');
  scope.solution.time = Math.max(0, scope.solution.time - 0.6);
}

function stepBullet(b, dt){
  if (!b.alive) return;
  const px=b.x, py=b.y, pz=b.z;
  const k = 0.0006 / Math.max(0.08,b.bc);
  const wx = mission.wind.vx, wz = mission.wind.vz;
  const rx=b.vx-wx, ry=b.vy, rz=b.vz-wz;
  const sp=Math.hypot(rx,ry,rz);
  b.vx += (-k*sp*rx)*dt;
  b.vy += (-9.81-k*sp*ry)*dt;
  b.vz += (-k*sp*rz)*dt;
  b.x += b.vx*dt; b.y += b.vy*dt; b.z += b.vz*dt;
  b.t += dt;
  const dist = Math.hypot(b.x-px,b.y-py,b.z-pz);
  b.startDist += dist;
  if (b.trail.length===0 || b.startDist - (b.trail[b.trail.length-1].d||0) > 3.5){
    b.trail.push({x:b.x,y:b.y,z:b.z,d:b.startDist});
    if (b.trail.length > 120) b.trail.shift();
  }
  // near-target miss tracking
  for (const t of mission.targets){
    if (!t.alive) continue;
    if (t.popup && !t.up) continue;
    if (Math.abs(b.z - t.z) < dist+1.8){
      const tx = t.x, ty = targetChestY(t), tz = t.z;
      const d = Math.hypot(b.x-tx, b.y-ty, b.z-tz);
      if (d < b.closest){ b.closest = d; b.closestTarget = t; b.closestOffsets = {dx:b.x-tx, dy:b.y-ty, dz:b.z-tz}; }
    }
  }
  // cover collisions
  for (const t of mission.targets){
    if (!t.alive) continue;
    const coverY0 = t.groundY, coverY1 = t.groundY + (t.popup && !t.up ? 1.32 : (t.cover?1.02:0));
    if (coverY1 <= coverY0) continue;
    if (b.ammo.id === 'ap') continue;
    const hit = segAABB(px,py,pz,b.x,b.y,b.z,
      t.x-0.68, coverY0, t.z-1.0, t.x+0.68, coverY1, t.z-0.32);
    if (hit !== null){
      b.alive = false;
      const ix=lerp(px,b.x,hit), iy=lerp(py,b.y,hit), iz=lerp(pz,b.z,hit);
      addImpact(ix,iy,iz,'dust');
      sfx('impact');
      showMissFeedback(b, ix, iy, iz);
      return;
    }
  }
  // target hitboxes
  for (const t of mission.targets){
    if (!t.alive) continue;
    if (t.popup && !t.up) continue;
    const head = segSphere(px,py,pz,b.x,b.y,b.z, t.x, targetHeadY(t), t.z, 0.145);
    if (head !== null){
      const ix=lerp(px,b.x,head), iy=lerp(py,b.y,head), iz=lerp(pz,b.z,head);
      b.alive = false; killTarget(t, true, ix, iy, iz, b);
      return;
    }
    const ty0 = t.groundY + (t.cover && b.ammo.id !== 'ap' ? 0.97 : (t.crouch?0.42:0.72));
    const ty1 = t.groundY + (t.crouch?1.08:1.51);
    const torso = segAABB(px,py,pz,b.x,b.y,b.z, t.x-0.30, ty0, t.z-0.24, t.x+0.30, ty1, t.z+0.24);
    if (torso !== null){
      const ix=lerp(px,b.x,torso), iy=lerp(py,b.y,torso), iz=lerp(pz,b.z,torso);
      b.alive = false; killTarget(t, false, ix, iy, iz, b);
      return;
    }
  }
  // ground
  if (b.y <= GROUND_Y){
    const f = clamp((py-GROUND_Y)/(py-b.y||1),0,1);
    const ix=lerp(px,b.x,f), iy=GROUND_Y, iz=lerp(pz,b.z,f);
    b.alive = false;
    addImpact(ix,iy,iz, currentWeather==='rain'?'splash':'dust');
    sfx('impact');
    showMissFeedback(b, ix, iy, iz);
    return;
  }
  if (b.z > 2300 || b.y < -100 || b.t > 6.5){
    b.alive = false;
    showMissFeedback(b, b.x, b.y, b.z);
  }
}

function segSphere(ax,ay,az,bx,by,bz,cx,cy,cz,r){
  const dx=bx-ax, dy=by-ay, dz=bz-az;
  const fx=ax-cx, fy=ay-cy, fz=az-cz;
  const a=dx*dx+dy*dy+dz*dz;
  if (a < 1e-9) return null;
  const b=2*(fx*dx+fy*dy+fz*dz);
  const c=fx*fx+fy*fy+fz*fz-r*r;
  let disc=b*b-4*a*c;
  if (disc<0) return null;
  disc=Math.sqrt(disc);
  const t1=(-b-disc)/(2*a), t2=(-b+disc)/(2*a);
  if (t1>=0 && t1<=1) return t1;
  if (t2>=0 && t2<=1) return t2;
  if (t1<0 && t2>1) return 0;
  return null;
}
function segAABB(ax,ay,az,bx,by,bz, x0,y0,z0, x1,y1,z1){
  const dx=bx-ax, dy=by-ay, dz=bz-az;
  let tmin=0, tmax=1;
  const axes=[[ax,dx,x0,x1],[ay,dy,y0,y1],[az,dz,z0,z1]];
  for (const [o,d,lo,hi] of axes){
    if (Math.abs(d)<1e-9){ if (o<lo||o>hi) return null; }
function updateAim(dt){
  if (state!=='mission' || !scope) return;
  const sens=view.fov/700;
  if (mouse.dx || mouse.dy){
    aim.yaw += mouse.dx*sens;
    aim.pitch -= mouse.dy*sens*0.86;
    mouse.dx=0; mouse.dy=0;
  }
  let ky=0,kp=0;
  if (keys['arrowleft']||keys['a']) ky-=1;
  if (keys['arrowright']||keys['d']) ky+=1;
  if (keys['arrowup']||keys['w']) kp+=1;
  if (keys['arrowdown']||keys['s']) kp-=1;
  if (ky||kp){
    const rate=view.fov*0.85;
    aim.yaw += ky*rate*dt;
    aim.pitch += kp*rate*0.72*dt;
  }
  // gamepad
  const gp=gamepadState;
  if (gp.index>=0){
    const ax=Math.abs(gp.axes[0])>0.16?gp.axes[0]:0;
    const ay=Math.abs(gp.axes[1])>0.16?gp.axes[1]:0;
    const rx=Math.abs(gp.axes[2])>0.16?gp.axes[2]:0;
    const ry=Math.abs(gp.axes[3])>0.16?gp.axes[3]:0;
    const rate=view.fov*1.05;
    aim.yaw += (ax*rate + rx*rate*0.26)*dt;
    aim.pitch += (-ay*rate*0.72 - ry*rate*0.20)*dt;
  }
  aim.yaw=clamp(aim.yaw,-0.88,0.88);
  aim.pitch=clamp(aim.pitch,-0.32,0.13);
}

function updateView(dt){
  if (state!=='mission' && state!=='paused' && state!=='debrief'){
    attract.t += dt;
    aim.yaw = attract.yaw + Math.sin(attract.t*0.08)*0.13;
    aim.pitch = attract.pitch + Math.sin(attract.t*0.13)*0.012;
    view.zoomT += (0-view.zoomT)*(1-Math.exp(-dt*8));
  } else if (state==='mission'){
    const target = (scope.scoped||mouse.right||gamepadState.scope>0.5) ? 1 : 0;
    view.zoomT += (target-view.zoomT)*(1-Math.exp(-dt*13));
    if (Math.abs(view.zoomT-target)<0.002) view.zoomT=target;
  }
  const lo=getLoadout();
  const hip=rad(62);
  view.fov = lerp(hip, lo.fov, view.zoomT);
  // sway
  const holding = scope && scope.holding;
  const bf = holding ? 0.16 : 1;
  const low = scope && scope.breath<=0 ? 1.85 : 1;
  const swayAmp = (0.00062 + 0.0039*(1-view.zoomT)) * lo.sway * bf * low;
  const t=ambientTime;
  let sy = (Math.sin(t*0.61+0.4)+0.55*Math.sin(t*1.73+1.2)+0.3*Math.sin(t*2.91))*0.5;
  let sp = (Math.sin(t*0.83+2.2)+0.4*Math.sin(t*2.17)+0.25*Math.sin(t*3.7))*0.5;
  if (holding) sp += Math.sin(t*7.2)*0.3;
  view.swayYaw = sy*swayAmp;
  view.swayPitch = sp*swayAmp*0.85;
  // recoil spring
  view.rvP += (-view.recoilPitch*105 - view.rvP*13)*dt;
  view.rvY += (-view.recoilYaw*105 - view.rvY*13)*dt;
  view.recoilPitch += view.rvP*dt;
  view.recoilYaw += view.rvY*dt;
  view.shake = Math.max(0, view.shake - dt*0.016);
  const shakeY = view.shake ? (Math.random()-0.5)*view.shake : 0;
  const shakeP = view.shake ? (Math.random()-0.5)*view.shake : 0;
  view.yaw = aim.yaw + view.swayYaw + view.recoilYaw + shakeY;
  view.pitch = aim.pitch + view.swayPitch + view.recoilPitch + shakeP;
}
function updateBullets(dt){
  for (const b of bullets){
    if (!b.alive) continue;
    let remaining=dt;
    let guard=0;
    while (remaining>0 && b.alive && guard++<60){
      const sp=Math.hypot(b.vx,b.vy,b.vz);
      const sub=Math.min(remaining, 1.15/Math.max(1,sp));
      stepBullet(b,sub);
      remaining-=sub;
    }
  }
  bullets=bullets.filter(b=>b.alive || b.t<0.9);
  // keep recently dead bullets for trail draw only briefly

  type: 'jpeg'
});
