function updateScopeState(dt){
  if (!scope) return;
  const lo=getLoadout();
  scope.cycle=Math.max(0,scope.cycle-dt);
  if (scope.reload>0){
    scope.reload-=dt;
    if (scope.reload<=0){ scope.ammo=lo.rifle.mag; scope.reload=0; sfx('reload'); addFeed('MAGAZINE READY','good'); }
  }
