function rangeFind(){
  if (!scope || state!=='mission' || mission.ended) return;
  if (scope.range.cool>0) return;
  scope.range.cool=1.1;
  let best=null, bestPx=1e9;
  const cx=W/2, cy=H/2;
  for (const t of mission.targets){
    if (!t.alive) continue;
    if (t.popup && !t.up) continue;
    const p=project(t.x,targetChestY(t),t.z);
    if (!p) continue;
    const d=Math.hypot(p.x-cx,p.y-cy);
    const radius = view.zoomT>0.5 ? 24 : 46;
    if (d<radius && d<bestPx){ bestPx=d; best=t; }
  }
  if (best){
    scope.range={dist:targetRange(best), time:7, targetId:best.id, exact:true, cool:1.1, tx:best.x, tz:best.z};
    sfx('range');
    addFeed(`LASER · ${Math.round(scope.range.dist)} M · CONTACT`,'good');
  } else {
    const fwd={x:Math.sin(view.yaw)*Math.cos(view.pitch),y:Math.sin(view.pitch),z:Math.cos(view.yaw)*Math.cos(view.pitch)};
    if (fwd.y < -0.002){
      const dist=(GROUND_Y-0)/fwd.y;
      if (dist>30 && dist<2400){
        scope.range={dist,time:6,targetId:-1,exact:false,cool:1.1};
        sfx('range');
        addFeed(`LASER · ${Math.round(dist)} M · TERRAIN`,'');
        return;
      }
    }
    scope.range={dist:0,time:0,targetId:-1,exact:false,cool:1.1};
    addFeed('LASER · NO RETURN','bad');
    sfx('empty');
  }
}
function applySolution(){
