  if (!scope.range.dist || scope.range.time<=0){ addFeed('RANGE REQUIRED · PRESS F','bad'); sfx('empty'); return; }
  const lo=getLoadout();
  const range=scope.range.dist;
  scope.zeroRange=clamp(Math.round(range/10)*10,100,1000);
  scope.zeroAngle=solveZeroAngle(lo.mv,lo.bc,scope.zeroRange);
  const r=simulateShot({mv:lo.mv,bc:lo.bc,angle:scope.zeroAngle,range,wind:windInAimFrame(mission.wind,view.yaw),dt:0.002});
  const elev=-r.y/range*1000;
  const windMil=-r.x/range*1000;
  scope.solution={elevMil:elev,windMil,active:true,time:12};
  sfx('solve');
  addFeed(`SOLUTION · ELEV ${Math.abs(elev).toFixed(1)} MIL · WIND ${Math.abs(windMil).toFixed(1)} MIL`,'good');
}
