  scope.zeroAngle=solveZeroAngle(lo.mv,lo.bc,scope.zeroRange);
  clearSolution();
  scope.ammo=Math.min(scope.ammo,lo.rifle.mag);
  sfx('click');
  addFeed('AMMO · '+AMMO_BY_ID[career.ammo].name,'');
  updateHUD(true);
}

