2892: let AC=null, master=null, ambientGain=null, noiseBuf=null;
2893: function initAudio(){
2894:   if (AC) return;
2895:   try {
2896:     AC=new (window.AudioContext||window.webkitAudioContext)();
2897:     master=AC.createGain(); master.gain.value=career.settings.mute?0:0.34; master.connect(AC.destination);
2898:     noiseBuf=AC.createBuffer(1,AC.sampleRate*1.5,AC.sampleRate);
2899:     const d=noiseBuf.getChannelData(0);
2900:     for (let i=0;i<d.length;i++) d[i]=Math.random()*2-1;
2901:     ambientGain=AC.createGain(); ambientGain.gain.value=0.025; ambientGain.connect(master);
2902:     const src=AC.createBufferSource(); src.buffer=noiseBuf; src.loop=true;
2903:     const lp=AC.createBiquadFilter(); lp.type='lowpass'; lp.frequency.value=380; lp.Q.value=0.5;
2904:     src.connect(lp); lp.connect(ambientGain); src.start();
2905:   } catch(e){}
2906: }
2907: function updateMute(){ if (master) master.gain.value=muted?0:0.34; }
2908: function startAmbient(){ initAudio(); if (AC && AC.state==='suspended') AC.resume(); }
2909: function tone(freq,dur,type,vol,slide){
2910:   if (!AC||muted) return;
2911:   const o=AC.createOscillator(), g=AC.createGain();
2912:   o.type=type||'sine'; o.frequency.value=freq;
2913:   if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(20,slide),AC.currentTime+dur);
2914:   g.gain.setValueAtTime(vol||0.08,AC.currentTime);
2915:   g.gain.exponentialRampToValueAtTime(0.0001,AC.currentTime+dur);
2916:   o.connect(g); g.connect(master); o.start(); o.stop(AC.currentTime+dur+0.02);
2917: }
2918: function noiseBurst(dur,filterFreq,vol,type){
2919:   if (!AC||muted||!noiseBuf) return;
2920:   const s=AC.createBufferSource(); s.buffer=noiseBuf;
2921:   const f=AC.createBiquadFilter(); f.type=type||'lowpass'; f.frequency.value=filterFreq||900;
2922:   const g=AC.createGain();
2923:   g.gain.setValueAtTime(vol||0.25,AC.currentTime);
2924:   g.gain.exponentialRampToValueAtTime(0.0001,AC.currentTime+dur);
2925:   s.connect(f); f.connect(g); g.connect(master); s.start(); s.stop(AC.currentTime+dur+0.03);
2926: }
2927: function sfx(type,tier){
2928:   if (!AC||muted) return;
2929:   switch(type){
2930:     case 'shot':
2931:       noiseBurst(0.16, 620-tier*70, 0.44, 'lowpass');
2932:       noiseBurst(0.05, 3000, 0.12, 'highpass');
2933:       tone(72-tier*3,0.22,'sine',0.28,38);
2934:       setTimeout(()=>{ if (AC&&!muted) noiseBurst(0.07,1400,0.10,'bandpass'); },180);
2935:       break;
2936:     case 'hit': tone(820,0.10,'square',0.06,540); noiseBurst(0.06,1400,0.10,'bandpass'); break;
2937:     case 'head': tone(1200,0.16,'triangle',0.09,700); tone(1700,0.12,'sine',0.05,900); break;
2938:     case 'impact': noiseBurst(0.12,500,0.08,'lowpass'); break;
2939:     case 'range': tone(1450,0.06,'square',0.035); setTimeout(()=>tone(1900,0.06,'square',0.03),70); break;
2940:     case 'solve': tone(620,0.08,'sine',0.05); setTimeout(()=>tone(880,0.10,'sine',0.05),80); setTimeout(()=>tone(1180,0.12,'sine',0.045),170); break;
2941:     case 'click': tone(1100,0.025,'square',0.025); break;
2942:     case 'bolt': noiseBurst(0.05,2200,0.12,'bandpass'); setTimeout(()=>noiseBurst(0.06,1200,0.10,'bandpass'),110); break;
2943:     case 'reload': tone(420,0.06,'square',0.04); setTimeout(()=>tone(720,0.07,'square',0.04),150); break;
2944:     case 'empty': tone(160,0.05,'square',0.03); break;
2945:     case 'buy': tone(680,0.08,'triangle',0.05); setTimeout(()=>tone(1020,0.12,'triangle',0.05),80); break;
2946:     case 'complete': tone(440,0.18,'triangle',0.06); setTimeout(()=>tone(660,0.18,'triangle',0.055),140); setTimeout(()=>tone(880,0.3,'triangle',0.05),280); break;
2947:     case 'fail': tone(220,0.3,'sine',0.06,110); break;
2948:     case 'thunder': noiseBurst(0.8,180,0.18,'lowpass'); break;
2949:   }
2950: }
