3019: function pollGamepad(dt){
3020:   const pads=navigator.getGamepads?navigator.getGamepads():[];
3021:   let gp=null;
3022:   if (pads){ for (const p of pads){ if (p&&p.connected){ gp=p; break; } } }
3023:   if (!gp){
3024:     if (gamepadState.index>=0){ gamepadState.index=-1; gamepadState.name=''; if (state==='title') showTitle(); }
3025:     return;
3026:   }
3027:   if (gamepadState.index!==gp.index){
3028:     gamepadState.index=gp.index; gamepadState.name=gp.id||'GAMEPAD';
3029:     if (state==='title') showTitle();
3030:   }
3031:   const ax=gp.axes||[];
3032:   gamepadState.axes=[ax[0]||0,ax[1]||0,ax[2]||0,ax[3]||0];
3033:   const btn=i=>gp.buttons[i] ? (gp.buttons[i].pressed||gp.buttons[i].value>0.4) : false;
3034:   const val=i=>gp.buttons[i] ? gp.buttons[i].value||0 : 0;
3035:   const prev=gamepadState.prev;
3036:   const edge=(i,name)=>btn(i)&&!prev[name];
3037:   gamepadState.breath=btn(4)?1:0;
3038:   gamepadState.scope=btn(6)?1:0;
3039:   if (state==='mission' && scope){
3040:     if (edge(7,'rt')) fireShot();
3041:     if (edge(5,'rb')) rangeFind();
3042:     if (edge(0,'a')) requestReload();
3043:     if (edge(1,'b')) cycleAmmo();
3044:     if (edge(3,'y')) applySolution();
3045:     if (edge(2,'x')){ scope.scoped=!scope.scoped; sfx('click'); }
3046:     if (edge(12,'du')) changeZero(1);
3047:     if (edge(13,'dd')) changeZero(-1);
3048:     if (edge(9,'start')) pauseGame();
3049:   } else if (state==='paused' && edge(9,'start')){
3050:     resumeGame();
3051:   } else if (state==='title' && (edge(0,'a')||edge(9,'start'))){
3052:     showBriefing();
3053:   } else if (state==='briefing'){
3054:     if (edge(0,'a')||edge(9,'start')) deployMission(career.op);
3055:     else if (edge(1,'b')) showTitle();
3056:   } else if (state==='debrief' && edge(0,'a')){
3057:     const next=$('btnDebriefNext'); if (next) next.click();
